103	function rasterPolygon(ctx,points,color) {
104	  ctx.fillStyle=C(color);
105	  for(let y=Math.max(0,Math.floor(Math.min(...points.map(p=>p[1]))));y<Math.min(180,Math.ceil(Math.max(...points.map(p=>p[1]))));y++) {
