115	function rasterLine(ctx,a,b,color) {
116	  let [x,y]=a.map(Math.round),[tx,ty]=b.map(Math.round);
117	  const dx=Math.abs(tx-x),dy=-Math.abs(ty-y),sx=x<tx?1:-1,sy=y<ty?1:-1;
118	  let err=dx+dy; ctx.fillStyle=C(color);
119	  while(true) { ctx.fillRect(x,y,1,1); if(x===tx&&y===ty)break;const e=2*err;if(e>=dy){err+=dy;x+=sx;}if(e<=dx){err+=dx;y+=sy;} }
