154	  for(let i=0;i<im.data.length;i+=4){const v=rand()>.48?255:84;im.data[i]=v;im.data[i+1]=v;im.data[i+2]=v;im.data[i+3]=rand()*85;}
155	  t.putImageData(im,0,0);ctx.save();ctx.globalAlpha=opacity;ctx.fillStyle=ctx.createPattern(texture,'repeat');ctx.fillRect(0,0,W,H);ctx.restore();
