182	    ctx.strokeStyle=C(m.color);ctx.lineWidth=Math.max(1.2,m.width*6);ctx.lineCap='round';ctx.shadowColor='rgba(60,50,30,.15)';ctx.shadowOffsetY=2;ctx.stroke();ctx.restore();
183	  }
184	  grain(ctx,.22);window.artCanvas=canvas;window.artReady=true;
185	}
186	function drawCrayon() {
187	  new p5(p=>{
188	    brush.instance(p);
189	    p.setup=()=>{
190	      const cnv=p.createCanvas(W,H,p.WEBGL);window.artCanvas=cnv.elt;
191	      p.pixelDensity(1);
192	      p.randomSeed(419);p.noiseSeed(419);p.angleMode(p.DEGREES);
193	      brush.scaleBrushes(3);p.noLoop();
194	    };
195	    p.draw=()=>{
196	      p.background('#f6efdf');p.translate(-W/2,-H/2);
197	      brush.noField();brush.noFill();brush.noHatch();
198	      for(const s of shapes) {
199	        if(s.name==='sky')continue;
200	        brush.set('2B',C(s.color),.28);
201	        brush.mass('crayon',C(s.color),{precision:.65,strength:.9,gradient:0,outline:false});
202	        brush.polygon(s.points.map(([x,y])=>[x*6,y*6]));
203	        brush.noMass();
204	      }
205	      for(const m of marks) {
206	        brush.set('2B',C(m.color),Math.max(.35,m.width*1.8));
207	        for(let i=1;i<m.points.length;i++)brush.line(...m.points[i-1].map(v=>v*6),...m.points[i].map(v=>v*6));
208	      }
209	      brush.noMass();brush.noFill();
210	      brush.set('crayon',C(1),.3);
211	      for(let i=0;i<30;i++){const y=30+i*12;brush.line(120+rand()*90,y,1200+rand()*500,y+rand()*7);}
212	      requestAnimationFrame(()=>{
213	        const output=document.createElement('canvas');output.width=W;output.height=H;
214	        const ctx=output.getContext('2d');ctx.drawImage(window.artCanvas,0,0,W,H);grain(ctx,.24);
215	        cnvRemove();document.body.append(output);window.artCanvas=output;window.brushNames=brush.box();window.artReady=true;
216	      });
217	      function cnvRemove(){window.artCanvas.style.display='none';}
218	    };
219	  });
220	}
221	if(STYLE==='pixel')drawPixel();
222	if(STYLE==='paper')drawPaper();
223	if(STYLE==='crayon')drawCrayon();
