// 三种画风共用的开场场景。坐标单位为 320×180 原生格，纸艺与蜡笔版乘以 U 得到 1920×1080。
export const W = 320, H = 180, U = 6;

export function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const COLORS = {
  sky: ['#a8c0c4', '#c2d2cc', '#e2dfc6', '#f3e4c4', '#f5d3a8', '#eebc90'],
  sun: '#fbe8a8', lamp: '#f6c35e',
  far: '#dccfb8', mid: '#b7c0b8', near: '#8aa0a6', nearDark: '#6b848c', rail: '#4f6873',
  red: '#d85a38', redDark: '#a8432f', white: '#f6efdf', whiteDark: '#d9cfbb',
  wood: '#b98a5c', woodDark: '#8f6545',
  floor: '#e6d3ae', floorDark: '#d3bc93', floorShadow: '#b8a98f',
  leaf: '#e5b547', leafDark: '#c9932f', branch: '#5f4a3e',
  caseBody: '#6f9087', caseDark: '#557269',
};

// 东京铁塔：中心 x=96，塔尖 y=14，塔基 y=131（被近景城市遮住）。
export const TOWER = {
  cx: 96, top: 14, base: 131,
  mainDeck: [88, 92, 11], topDeck: [52, 57, 4],
  bands: [[14, 24, 'red'], [24, 34, 'white'], [34, 52, 'red'], [52, 57, 'white'], [57, 68, 'white'], [68, 78, 'red'],
    [78, 88, 'white'], [88, 92, 'white'], [92, 104, 'red'], [104, 118, 'white'], [118, 131, 'red']],
};

export function towerHalf(y) {
  const [ma, mb, mw] = TOWER.mainDeck, [ta, tb, tw] = TOWER.topDeck;
  if (y >= mb) return 9 + 8 * Math.pow((y - mb) / (TOWER.base - mb), 1.8);
  if (y >= ma) return mw;
  if (y >= tb) return 3 + 5 * Math.pow((y - tb) / (ma - tb), 1.3);
  if (y >= ta) return tw;
  if (y >= 34) return 1 + (y - 34) / 18;
  return 0.5 + 0.5 * (y - 14) / 20;
}

// 塔脚之间的拱门内半宽；0 表示此高度没有开口。
export function towerArch(y) {
  if (y <= 116) return 0;
  return Math.max(0, (towerHalf(y) - 4) * Math.sqrt((y - 116) / 15));
}

// 三层城市，由固定种子生成：far、mid 在塔后，near 遮住塔基。
function buildSkyline(seed, [minTop, maxTop], [minW, maxW], lightOdds) {
  const r = rng(seed), buildings = [], lights = [];
  for (let x = -4; x < W + 4;) {
    const w = Math.round(minW + r() * (maxW - minW)), top = Math.round(minTop + r() * (maxTop - minTop));
    buildings.push({x, w, top});
    for (let wy = top + 3; wy < 145; wy += 4) {
      for (let wx = x + 2; wx < x + w - 1; wx += 3) {
        if (r() < lightOdds) lights.push({x: wx, y: wy, warm: r() < 0.7});
      }
    }
    x += w;
  }
  return {buildings, lights};
}
export const SKYLINE = {
  far: buildSkyline(1031, [103, 117], [8, 20], 0),
  mid: buildSkyline(2207, [109, 125], [7, 16], 0.05),
  near: buildSkyline(3119, [121, 132], [6, 14], 0.15),
};

// 把一层楼房合成为阶梯轮廓，底边落在露台矮墙后。
export function skylinePolygon(layer, bottom = 147) {
  const pts = [[-4, bottom]];
  for (const b of layer.buildings) { pts.push([b.x, b.top], [b.x + b.w, b.top]); }
  pts.push([W + 4, bottom]);
  return pts;
}

export const SUN = {x: 168, y: 103, r: 13};

// 从高空坠向城市的光点：呼应 L02「燈火模仿 墜落的星光」。
export const STARS = [[222, 16, 2], [208, 30, 2], [192, 46, 1], [176, 62, 1], [160, 78, 0], [146, 92, 0]];

export const RAIL = {top: 131, low: 137, wall: 141, floor: 146, posts: [12, 42, 72, 102, 132, 162, 192, 222, 252, 282, 312]};

// 无靠背长椅：右半坐着主角，左半空着，放两张车票。
export const BENCH = {
  x: 170, w: 76, top: 143, h: 5,
  legs: [[176, 148, 4, 14], [236, 148, 4, 14]],
  brace: [180, 154, 56, 2],
};
export const CLAWD = {x: 206, y: 121};
export const TICKETS = [
  [[180, 140], [188, 139], [189, 143], [181, 143]],
  [[187, 141], [195, 140], [195, 143], [188, 143]],
];
export const SUITCASE = {
  body: [253, 146, 16, 17], handle: [257, 143, 8, 3], straps: [[257, 146, 1, 17], [264, 146, 1, 17]],
};
// 日落在主角左后方，影子落向画面右下。
export const SHADOW = [[172, 161], [246, 161], [288, 180], [204, 180]];
export const CASE_SHADOW = [[253, 163], [269, 163], [290, 174], [272, 174]];

// 画面右上角前景银杏枝。
export const BRANCH = [[[322, 5], [292, 9], [266, 16], [246, 19]], [[292, 9], [278, 2], [270, -2]], [[266, 16], [254, 26]]];
export const LEAVES = [[248, 19], [243, 23], [254, 26], [259, 29], [268, 18], [262, 12], [276, 13], [283, 6],
  [290, 15], [298, 9], [305, 14], [312, 11], [272, 2], [251, 13]];
export const leafShape = (x, y, flip = 1) => [[x, y - 2], [x + 3 * flip, y - 1], [x + 3 * flip, y + 1], [x, y + 2], [x - 1 * flip, y]];

import {drawCharacter, CHARACTER_COLORS as CC} from '../../../assets/clawd/character.js';
import {W, H, U, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH, CLAWD,
  TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const BAYER = [[0, 32, 8, 40, 2, 34, 10, 42], [48, 16, 56, 24, 50, 18, 58, 26], [12, 44, 4, 36, 14, 46, 6, 38],
  [60, 28, 52, 20, 62, 30, 54, 22], [3, 35, 11, 43, 1, 33, 9, 41], [51, 19, 59, 27, 49, 17, 57, 25],
  [15, 47, 7, 39, 13, 45, 5, 37], [63, 31, 55, 23, 61, 29, 53, 21]];
const dither = (x, y) => (BAYER[y & 7][x & 7] + 0.5) / 64;

export function drawPixel() {
  const native = document.createElement('canvas');
  native.width = W; native.height = H;
  const ctx = native.getContext('2d');
  const plot = (x, y, color) => {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    ctx.fillStyle = color; ctx.fillRect(x, y, 1, 1);
  };
  const box = (x, y, w, h, color) => { for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) plot(i, j, color); };
  const poly = (pts, color) => {
    const ys = pts.map(p => p[1]);
    for (let y = Math.floor(Math.min(...ys)); y <= Math.ceil(Math.max(...ys)); y++) {
      const xs = [];
      pts.forEach(([ax, ay], i) => {
        const [bx, by] = pts[(i + 1) % pts.length];
        if ((ay <= y + 0.5) !== (by <= y + 0.5)) xs.push(ax + (y + 0.5 - ay) * (bx - ax) / (by - ay));
      });
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) for (let x = Math.round(xs[k]); x < Math.round(xs[k + 1]); x++) plot(x, y, typeof color === 'function' ? color(x, y) : color);
    }
  };
  const line = (a, b, color) => {
    let [x, y] = a; const [tx, ty] = b;
    const dx = Math.abs(tx - x), dy = -Math.abs(ty - y), sx = x < tx ? 1 : -1, sy = y < ty ? 1 : -1;
    let err = dx + dy;
    while (true) {
      plot(x, y, color);
      if (x === tx && y === ty) break;
      const e = 2 * err;
      if (e >= dy) { err += dy; x += sx; }
      if (e <= dx) { err += dx; y += sy; }
    }
  };

  // 天空：六色之间只用 Bayer 点阵过渡。
  for (let y = 0; y < 147; y++) for (let x = 0; x < W; x++) {
    const t = Math.pow(y / 118, 1.15) * (C.sky.length - 1);
    const base = Math.min(C.sky.length - 1, Math.floor(t));
    const pick = t - base > dither(x, y) ? Math.min(C.sky.length - 1, base + 1) : base;
    plot(x, y, C.sky[pick]);
  }
  for (let y = SUN.y - SUN.r; y <= SUN.y + SUN.r; y++) for (let x = SUN.x - SUN.r; x <= SUN.x + SUN.r; x++) {
    if (Math.hypot(x - SUN.x, y - SUN.y) <= SUN.r) plot(x, y, C.sun);
  }
  for (const [x, y, size] of STARS) {
    plot(x, y, C.lamp);
    if (size >= 1) { plot(x - 1, y, C.lamp); plot(x + 1, y, C.lamp); plot(x, y - 1, C.lamp); plot(x, y + 1, C.lamp); }
    if (size >= 2) { plot(x, y, C.sun); plot(x - 2, y, C.lamp); plot(x + 2, y, C.lamp); plot(x, y - 2, C.lamp); plot(x, y + 2, C.lamp); }
  }

  poly(skylinePolygon(SKYLINE.far), C.far);
  poly(skylinePolygon(SKYLINE.mid), C.mid);
  for (const l of SKYLINE.mid.lights) plot(l.x, l.y, l.warm ? C.sun : C.far);

  // 铁塔：逐行画立柱与交叉桁架，桁架之间透出后方。
  const bandColor = y => TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] || 'red';
  for (let y = TOWER.top; y < TOWER.base; y++) {
    const half = towerHalf(y), arch = towerArch(y), key = bandColor(y);
    const hi = key === 'red' ? C.red : C.white, lo = key === 'red' ? C.redDark : C.whiteDark;
    const r = Math.round(half);
    for (let dx = -r; dx <= r; dx++) {
      const x = TOWER.cx + dx, abs = Math.abs(dx);
      if (arch && abs < arch) continue;
      const deck = (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) || (y >= TOWER.topDeck[0] && y < TOWER.topDeck[1]);
      const edge = r - abs < 2, brace = (x + y) % 7 === 0 || (x - y + 700) % 7 === 0, girder = y % 7 === 0;
      if (deck || r <= 2 || edge || brace || girder) plot(x, y, dx > 0 && !deck ? lo : hi);
    }
  }
  for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
    for (let x = TOWER.cx - half + 1; x < TOWER.cx + half; x += 2) plot(x, a + 1, C.rail);
    box(TOWER.cx - half, b - 1, half * 2 + 1, 1, C.redDark);
  }

  // 近景楼房、窗灯、栏杆与矮墙。
  poly(skylinePolygon(SKYLINE.near), (x, y) => (y > 138 && (x + y) % 2 === 0 ? C.nearDark : C.near));
  for (const l of SKYLINE.near.lights) plot(l.x, l.y, l.warm ? C.lamp : C.sun);
  box(0, RAIL.top, W, 1, C.rail); box(0, RAIL.low, W, 1, C.nearDark);
  for (const x of RAIL.posts) box(x, RAIL.top, 1, RAIL.wall - RAIL.top, C.rail);
  box(0, RAIL.wall, W, RAIL.floor - RAIL.wall, C.nearDark);
  box(0, RAIL.wall, W, 1, C.rail);

  // 地面：横缝加点阵暖光。
  for (let y = RAIL.floor; y < H; y++) for (let x = 0; x < W; x++) {
    const glow = 1 - Math.min(1, Math.abs(x - SUN.x) / 150) - (y - RAIL.floor) / 90;
    plot(x, y, glow * 0.8 > dither(x, y) ? C.floor : C.floorDark);
  }
  for (const y of [152, 160, 171]) box(0, y, W, 1, C.floorShadow);

  poly(SHADOW, (x, y) => ((x + y) % 2 === 0 ? C.floorShadow : C.floorDark));
  poly(CASE_SHADOW, (x, y) => ((x + y) % 2 === 0 ? C.floorShadow : C.floorDark));

  for (const [x, y, w, h] of BENCH.legs) box(x, y, w, h, C.branch);
  box(...BENCH.brace, C.woodDark);

  const c = SUITCASE;
  box(c.handle[0], c.handle[1], c.handle[2], 1, C.branch);
  box(c.handle[0], c.handle[1], 1, c.handle[3], C.branch);
  box(c.handle[0] + c.handle[2] - 1, c.handle[1], 1, c.handle[3], C.branch);
  box(...c.body, C.caseBody);
  box(c.body[0] + c.body[2] - 3, c.body[1], 3, c.body[3], C.caseDark);
  box(c.body[0], c.body[1] + c.body[3] - 1, c.body[2], 1, C.branch);
  for (const s of c.straps) box(...s, C.whiteDark);

  drawCharacter(ctx, {x: CLAWD.x, y: CLAWD.y, scale: 1, facing: 'back', expression: 'sad', action: 'idle', frame: 0});

  // 长椅面在主角之后画，盖住背向镜头时看不见的腿。
  box(BENCH.x, BENCH.top, BENCH.w, 1, C.wood);
  box(BENCH.x, BENCH.top + 1, BENCH.w, BENCH.h - 2, C.wood);
  box(BENCH.x, BENCH.top + BENCH.h - 1, BENCH.w, 1, C.woodDark);
  for (let x = BENCH.x + 6; x < BENCH.x + BENCH.w; x += 9) plot(x, BENCH.top + 2, C.woodDark);

  TICKETS.forEach((t, i) => {
    poly(t, C.white);
    const [ax, ay] = t[i === 0 ? 0 : 1];
    line([ax + (i === 0 ? 1 : -2), ay + 1], [ax + (i === 0 ? 1 : -2), ay + 2], C.red);
  });

  for (const pts of BRANCH) for (let i = 1; i < pts.length; i++) line(pts[i - 1], pts[i], C.branch);
  LEAVES.forEach(([x, y], i) => poly(leafShape(x, y, i % 2 ? 1 : -1), i % 3 === 0 ? C.leafDark : C.leaf));

  const canvas = document.createElement('canvas');
  canvas.width = W * U; canvas.height = H * U; document.body.append(canvas);
  const out = canvas.getContext('2d');
  out.imageSmoothingEnabled = false;
  out.drawImage(native, 0, 0, canvas.width, canvas.height);
  void CC;
  return {canvas, native};
}

// 用本机 Chrome 无头渲染样图并自检。用法：node render.mjs [pixel paper crayon]
import {spawn} from 'node:child_process';
import {createServer} from 'node:http';
import {readFile, writeFile, mkdtemp, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../../..');
const FILES = {pixel: '01-像素遊戲', paper: '02-紙藝拼貼', crayon: '03-蠟筆手繪'};
const styles = process.argv.slice(2).length ? process.argv.slice(2) : Object.keys(FILES);
const CHROME = process.env.CHROME || '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const MIME = {'.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript'};

const server = createServer(async (req, res) => {
  try {
    const file = path.join(root, decodeURIComponent(new URL(req.url, 'http://x').pathname));
    if (!file.startsWith(root)) throw new Error('outside root');
    res.writeHead(200, {'content-type': MIME[path.extname(file)] || 'application/octet-stream'});
    res.end(await readFile(file));
  } catch { res.writeHead(404); res.end(); }
});
await new Promise(ok => server.listen(0, '127.0.0.1', ok));
const port = server.address().port;

const profile = await mkdtemp(path.join(process.env.TMPDIR || tmpdir(), 'opening-chrome-'));
const chrome = spawn(CHROME, ['--headless=new', '--remote-debugging-port=0', `--user-data-dir=${profile}`,
  '--window-size=1920,1080', '--force-device-scale-factor=1', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
  '--ignore-gpu-blocklist', '--no-first-run', 'about:blank'], {stdio: ['ignore', 'ignore', 'pipe']});
const wsUrl = await new Promise((ok, fail) => {
  let log = '';
  chrome.stderr.on('data', d => { log += d; const m = log.match(/ws:\/\/\S+/); if (m) ok(m[0]); });
  chrome.on('exit', code => fail(new Error(`Chrome 退出 ${code}: ${log}`)));
});

const ws = new WebSocket(wsUrl);
await new Promise((ok, fail) => { ws.onopen = ok; ws.onerror = fail; });
let id = 0;
