/* global p5, brush */
import {W, H, U, rng, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH,
  CLAWD_PARTS, TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const PX = W * U, PY = H * U;
const r = rng(7741);
const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];

// 把多边形扫描成一组平行线段，线段就是一笔一笔的蜡笔排线。
function hatchSpans(points, angle, gap) {
  const a = angle * Math.PI / 180, cos = Math.cos(a), sin = Math.sin(a);
  const rot = points.map(([x, y]) => [x * cos + y * sin, -x * sin + y * cos]);
  const vs = rot.map(p => p[1]), spans = [];
  for (let v = Math.min(...vs) + gap * 0.4; v < Math.max(...vs); v += gap * (0.8 + r() * 0.4)) {
    const hits = [];
    rot.forEach(([x0, y0], i) => {
      const [x1, y1] = rot[(i + 1) % rot.length];
      if ((y0 <= v) !== (y1 <= v)) hits.push(x0 + (v - y0) * (x1 - x0) / (y1 - y0));
    });
    hits.sort((p, q) => p - q);
    for (let k = 0; k + 1 < hits.length; k += 2) {
      spans.push([[hits[k], v], [hits[k + 1], v]].map(([u, w]) => [u * cos - w * sin, u * sin + w * cos]));
    }
  }
  return spans;
}

function scribble(points, color, {angle = 20, gap = 9, weight = 1, over = 3, alpha = 1, wob = 3} = {}) {
  const px = points.map(([x, y]) => [x * U, y * U]);
  brush.set('crayon', color, weight);
  for (const [[x0, y0], [x1, y1]] of hatchSpans(px, angle + (r() - 0.5) * 3, gap)) {
    const len = Math.hypot(x1 - x0, y1 - y0);
    if (len < 2) continue;
    const ox = (x1 - x0) / len * (r() - 0.3) * over, oy = (y1 - y0) / len * (r() - 0.3) * over;
    const mx = (x0 + x1) / 2 + (r() - 0.5) * wob, my = (y0 + y1) / 2 + (r() - 0.5) * wob;
    if (len < 40) brush.line(x0 - ox, y0 - oy, x1 + ox, y1 + oy);
    else brush.spline([[x0 - ox, y0 - oy, 0.75 * alpha], [mx, my, alpha], [x1 + ox, y1 + oy, 0.8 * alpha]], 0.5);
  }
}

function outline(points, color, weight = 0.5, name = '2B', closed = true) {
  brush.set(name, color, weight);
  const pts = closed ? [...points, points[0]] : points;
  for (let i = 1; i < pts.length; i++) {
    const j = 1.6;
    brush.line(pts[i - 1][0] * U + (r() - 0.5) * j, pts[i - 1][1] * U + (r() - 0.5) * j, pts[i][0] * U + (r() - 0.5) * j, pts[i][1] * U + (r() - 0.5) * j);
  }
}

function paint() {
  // 天空：从上到下换色长排线，故意留白露出纸面。
  const bands = [[-6, 34, C.sky[0]], [24, 58, C.sky[1]], [48, 82, C.sky[2]], [72, 102, C.sky[3]], [92, 120, C.sky[4]], [108, 147, C.sky[5]]];
  for (const [a, b, color] of bands) {
    scribble(rect(-6, a, W + 12, b - a), color, {angle: -5, gap: 21, weight: 3.8, over: 30, wob: 20});
  }

  const sun = Array.from({length: 28}, (_, i) => [SUN.x + Math.cos(i / 28 * 6.283) * SUN.r, SUN.y + Math.sin(i / 28 * 6.283) * SUN.r]);
  scribble(sun, '#f8d978', {angle: 30, gap: 7, weight: 1.5, over: 1});
  scribble(sun, C.sun, {angle: -40, gap: 12, weight: 1.2, over: 1});

  for (const [x, y, size] of STARS) {
    const a = (1.5 + size * 1.4) * U;
    brush.set('crayon', '#e29f35', 0.7 + size * 0.3);
    brush.line(x * U - a, y * U, x * U + a, y * U);
    brush.line(x * U, y * U - a, x * U, y * U + a);
  }

  scribble(skylinePolygon(SKYLINE.far), C.far, {angle: 88, gap: 11, weight: 1.6, over: 2});
  scribble(skylinePolygon(SKYLINE.mid), C.mid, {angle: 80, gap: 10, weight: 1.7, over: 2});
  scribble(skylinePolygon(SKYLINE.mid), '#94a7a5', {angle: 62, gap: 34, weight: 1.1, over: 2});
  for (const l of SKYLINE.mid.lights) {
    brush.set('crayon', l.warm ? '#f3cf74' : C.far, 0.8);
    brush.line(l.x * U, l.y * U, l.x * U + 5, l.y * U + 1);
  }

  // 铁塔分色涂满再压桁架，塔身是全图唯一接近满涂的地方。
  for (const [a, b, key] of TOWER.bands) {
    const rows = [];
    for (let y = a; y <= b; y++) rows.push(y);
    const leftSide = rows.map(y => [TOWER.cx - towerHalf(y), y]);
    const rightSide = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
    if (a >= 117) {
      const lo = rows.map(y => [TOWER.cx - towerHalf(y), y]), inL = rows.slice().reverse().map(y => [TOWER.cx - Math.max(towerArch(y), 0.1), y]);
      const inR = rows.map(y => [TOWER.cx + Math.max(towerArch(y), 0.1), y]), ro = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
      for (const leg of [[...lo, ...inL], [...inR, ...ro]]) {
        scribble(leg, C.red, {angle: 70, gap: 4.5, weight: 1, over: 1, wob: 1});
      }
      continue;
    }
    const band = [...leftSide, ...rightSide];
    const color = key === 'red' ? C.red : C.white;
    scribble(band, color, {angle: 72, gap: key === 'red' ? 4.5 : 7, weight: b - a < 12 && a < 57 ? 0.8 : 1, over: 1, wob: 1});
    if (key === 'white') scribble(band, C.whiteDark, {angle: -50, gap: 14, weight: 0.7, over: 1, wob: 1});
  }
  for (let y = 58; y < TOWER.base - 6; y += 6) {
    if (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) continue;
    const h1 = towerHalf(y), h2 = towerHalf(y + 6), red = TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] === 'red';
    brush.set('2B', red ? '#8c3525' : '#a4977f', 0.55);
    brush.line((TOWER.cx - h1) * U, y * U, (TOWER.cx + h2) * U, (y + 6) * U);
    brush.line((TOWER.cx + h1) * U, y * U, (TOWER.cx - h2) * U, (y + 6) * U);
  }
  const edgeL = [], edgeR = [];
  for (let y = TOWER.top; y <= 128; y += 2) { edgeL.push([TOWER.cx - towerHalf(y), y]); edgeR.push([TOWER.cx + towerHalf(y), y]); }
  outline(edgeL, '#8c3525', 0.6, '2B', false);
  outline(edgeR, '#8c3525', 0.6, '2B', false);
  for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
    scribble(rect(TOWER.cx - half, a, half * 2, b - a), C.white, {angle: 5, gap: 5, weight: 1, over: 1, wob: 1});
    outline(rect(TOWER.cx - half, a, half * 2, b - a), '#6d4a3c', 0.6);
    brush.set('crayon', C.rail, 0.8);
    for (let x = TOWER.cx - half + 1; x < TOWER.cx + half - 0.5; x += 2) brush.line(x * U, (a + 1) * U, x * U + 3, (a + 2) * U);
  }

  scribble(skylinePolygon(SKYLINE.near), C.near, {angle: 76, gap: 7.5, weight: 1.9, over: 2});
  scribble(skylinePolygon(SKYLINE.near), C.nearDark, {angle: 52, gap: 19, weight: 1.3, over: 2});
  for (const l of SKYLINE.near.lights) {
    brush.set('crayon', l.warm ? C.lamp : C.sun, 1.1);
    brush.line(l.x * U, l.y * U, l.x * U + 9, l.y * U + 1);
    if (l.warm) brush.line(l.x * U + 1, l.y * U + 4, l.x * U + 8, l.y * U + 4);
  }

  brush.set('crayon', C.rail, 1.2);
  brush.spline([[-20, RAIL.top * U + 2], [PX / 2, RAIL.top * U - 3], [PX + 20, RAIL.top * U + 2]], 0.3);
  brush.set('crayon', C.nearDark, 0.8);
  brush.spline([[-20, RAIL.low * U], [PX / 2, RAIL.low * U + 3], [PX + 20, RAIL.low * U - 1]], 0.3);
  for (const x of RAIL.posts) {
    brush.set('crayon', C.rail, 0.9);
    brush.line(x * U, RAIL.top * U, x * U + (r() - 0.5) * 3, RAIL.wall * U);
  }
  scribble(rect(-4, RAIL.wall, W + 8, RAIL.floor - RAIL.wall), C.nearDark, {angle: 8, gap: 6, weight: 1.4, over: 6});

  scribble(rect(-4, RAIL.floor, W + 8, H - RAIL.floor + 4), C.floor, {angle: -7, gap: 13, weight: 3.2, over: 30, wob: 12});
  scribble([[-4, 158], [150, 150], [130, H + 4], [-4, H + 4]], C.floorDark, {angle: 20, gap: 22, weight: 2.4, over: 10, wob: 10});
  scribble([[250, RAIL.floor], [W + 4, RAIL.floor], [W + 4, H + 4], [270, H + 4]], C.floorDark, {angle: 20, gap: 26, weight: 2.2, over: 10, wob: 10});
  for (const shade of [SHADOW, CASE_SHADOW]) scribble(shade, '#a99a80', {angle: 32, gap: 8, weight: 1.7, over: 2});

  for (const leg of BENCH.legs) {
    scribble(rect(...leg), C.branch, {angle: 84, gap: 3.5, weight: 1, over: 1, wob: 1});
  }
  scribble(rect(...BENCH.brace), C.woodDark, {angle: 2, gap: 4, weight: 0.9, over: 2, wob: 1});

  const c = SUITCASE;
  outline([[c.handle[0], c.body[1]], [c.handle[0], c.handle[1]], [c.handle[0] + c.handle[2], c.handle[1]], [c.handle[0] + c.handle[2], c.body[1]]], C.branch, 1.1, 'crayon', false);
  scribble(rect(...c.body), C.caseBody, {angle: 75, gap: 5.5, weight: 1.5, over: 1, wob: 2});
  scribble(rect(c.body[0] + c.body[2] - 4, c.body[1], 4, c.body[3]), C.caseDark, {angle: 70, gap: 4.5, weight: 1, over: 1, wob: 1});
  for (const s of c.straps) { brush.set('crayon', C.white, 0.9); brush.line(s[0] * U + 3, s[1] * U, s[0] * U + 3, (s[1] + s[3]) * U); }
  outline(rect(...c.body), '#3f5650', 0.55);

  // 主角按 32 格比例重画，涂得最满最深，是画面视线的落点。
  const p = CLAWD_PARTS;
  for (const leg of p.legs) scribble(rect(...leg), '#a84f3c', {angle: 88, gap: 3.2, weight: 0.9, over: 1, wob: 1});

  scribble(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), C.wood, {angle: 3, gap: 5, weight: 1.5, over: 5, wob: 2});
  scribble(rect(BENCH.x, BENCH.top + 3, BENCH.w, 2), C.woodDark, {angle: 1, gap: 4, weight: 0.9, over: 3, wob: 1});
  outline(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), '#5c3f2e', 0.6);
  for (const leg of p.legs) scribble(rect(leg[0], leg[1] + 1, leg[2], 5), '#a84f3c', {angle: 88, gap: 3.2, weight: 0.9, over: 1, wob: 1});

  scribble(rect(...p.armBack), '#a84f3c', {angle: 10, gap: 4, weight: 1, over: 1, wob: 1});
  scribble(rect(...p.body), '#da7758', {angle: 58, gap: 5, weight: 1.7, over: 1, wob: 2});
  scribble(rect(...p.body), '#c9654a', {angle: -38, gap: 11, weight: 1.1, over: 1, wob: 2});
  scribble(rect(p.body[0], p.body[1] + 2, 3, p.body[3] - 2), '#a84f3c', {angle: 80, gap: 4, weight: 1, over: 1, wob: 1});
  scribble(rect(p.body[0] + 2, p.body[1], p.body[2] - 3, 1.5), '#f0a57f', {angle: 2, gap: 4, weight: 0.9, over: 1, wob: 1});
  outline(rect(...p.body), '#713f32', 0.75);
  scribble(rect(...p.arm), '#ed9b75', {angle: 10, gap: 3.5, weight: 1, over: 1, wob: 1});
  outline(rect(...p.arm), '#713f32', 0.6);
  scribble(rect(...p.eye), '#352e2a', {angle: 85, gap: 2.2, weight: 0.8, over: 0.5, wob: 0.5});
  brush.set('crayon', '#5da6bd', 0.8);
  brush.line((p.tear[0] + 0.5) * U, p.tear[1] * U, (p.tear[0] + 0.5) * U, (p.tear[1] + p.tear[3] + 1) * U);

  TICKETS.forEach((t, i) => {
    scribble(t, C.white, {angle: 10, gap: 4, weight: 1, over: 1, wob: 1});
    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
    scribble(rect(stub, Math.max(t[0][1], t[1][1]) + 0.3, 2, 4), C.red, {angle: 85, gap: 3, weight: 0.8, over: 0.5, wob: 1});
    outline(t, '#6d4a3c', 0.5);
  });

  for (const pts of BRANCH) outline(pts, C.branch, 1.25, 'crayon', false);
  LEAVES.forEach(([x, y], i) => {
    const s = leafShape(x, y, i % 2 ? 1 : -1).map(([a, b]) => [x + (a - x) * 1.25, y + (b - y) * 1.25]);
    scribble(s, i % 3 === 0 ? C.leafDark : C.leaf, {angle: 40 + i * 13, gap: 3.5, weight: 1, over: 1, wob: 1});
  });
}

export function drawCrayon(done) {
  new p5(p => {
    brush.instance(p);
    p.setup = () => {
      const cnv = p.createCanvas(PX, PY, p.WEBGL);
