      ctx.fillStyle = C.caseDark; ctx.fillRect((c.body[0] + c.body[2] - 3) * U, 0, 3 * U, PY);
    }});
    for (const s of c.straps) piece(rect(...s), {color: C.whiteDark, border: 2, lift: 0.2});
