  const plank = layer(() => {
    piece(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), {color: C.wood, lift: 1.2, detail: () => {
      for (let i = 0; i < 26; i++) {
        const y = (BENCH.top + r() * BENCH.h) * U, x = (BENCH.x + r() * BENCH.w * 0.8) * U;
        ctx.strokeStyle = 'rgba(92,62,38,.4)'; ctx.lineWidth = 1 + r() * 1.5;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.bezierCurveTo(x + 40, y + 2, x + 80, y - 2, x + 90 + r() * 70, y + 1); ctx.stroke();
      }
    }});
  });

  const clawdId = layerCount++;
  const poses = new Map();
  const pose = (action, frame) => {
    const key = `${action}:${frame}`;
    if (!poses.has(key)) {
      const canvas = makeCanvas();
      ctx = canvas.getContext('2d');
      const p = clawdParts(CLAWD.x, CLAWD.y, action, frame);
      if (action === 'walk') {
        ctx.fillStyle = 'rgba(84,62,42,.3)';
        ctx.beginPath(); ctx.ellipse((CLAWD.x + 16) * U, (CLAWD.y + 27) * U, 9 * U, 1.6 * U, 0, 0, 7); ctx.fill();
      }
      piece(rect(...p.armBack), {color: '#b85d47', border: 5, lift: 0.5});
      for (const leg of p.legs) piece(rect(...leg), {color: '#b85d47', border: 4, lift: 0.5});
      piece(rect(...p.body), {color: '#da7758', lift: 1.5, detail: () => {
        ctx.fillStyle = '#b85d47'; ctx.fillRect(p.body[0] * U, 0, 2.2 * U, PY);
        ctx.fillStyle = '#ed9b75'; ctx.fillRect(p.body[0] * U, p.body[1] * U, p.body[2] * U, 1.3 * U);
      }});
      piece(rect(...p.arm), {color: '#ed9b75', border: 5, lift: 0.8});
      piece(rect(...p.eye), {color: '#352e2a', border: 3, lift: 0.2});
      poses.set(key, canvas);
    }
    return poses.get(key);
  };
  const tickets = layer(() => TICKETS.forEach((t, i) => piece(t, {color: C.white, border: 4, lift: 0.8, detail: () => {
    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
    ctx.fillStyle = C.red; ctx.fillRect(stub * U, 0, 2 * U, PY);
  }})));
  const branch = layer(() => {
    for (const pts of BRANCH) stripe(pts, C.branch, 7, 4);
    LEAVES.forEach(([x, y], i) => {
      const s = leafShape(x, y, i % 2 ? 1 : -1).map(([a, b]) => [x + (a - x) * 1.25, y + (b - y) * 1.25]);
      piece(s, {color: i % 3 === 0 ? C.leafDark : C.leaf, border: 3, lift: 0.6});
    });
  });

  const canvas = makeCanvas();
  document.body.append(canvas);
  const out = canvas.getContext('2d');

  function render(s, tick = null) {
    const shake = id => (tick === null ? {dx: 0, dy: 0} : jitter(id, tick));
    const put = (l, ox = 0, oy = 0) => {
      const {dx, dy} = shake(l.id);
      out.drawImage(l.canvas, ox + dx, oy + dy);
    };
    const lights = (list, offset, l, width, color) => {
      const {dx, dy} = shake(l.id);
      out.save();
      out.shadowColor = 'rgba(40,40,30,.35)'; out.shadowBlur = 2; out.shadowOffsetY = 1;
      list.forEach((light, i) => {
        if (!isLit(i + offset, s.lit)) return;
        out.fillStyle = color(light);
        out.fillRect(light.x * U + dx, light.y * U + dy, width, 8);
      });
      out.restore();
    };
    out.drawImage(base, 0, 0);
    put(sky); put(sun);
    stars.slice(0, s.stars).forEach(l => put(l));
    put(far); put(mid);
    lights(SKYLINE.mid.lights, 0, mid, 7, l => (l.warm ? C.sun : CORE));
    put(tower); put(near);
    lights(SKYLINE.near.lights, 1000, near, 10, l => (l.warm ? C.lamp : C.sun));
    put(rail); put(floor); put(benchLegs);
    put(suitcase, (s.caseX - SUITCASE.body[0]) * U);
    put(plank);
    put({canvas: pose(s.action, s.frame), id: clawdId}, (s.x - CLAWD.x) * U, (s.y - CLAWD.y) * U);
    put(tickets); put(branch);
  }
  return {canvas, render};
}

