1	/* global p5, brush */
2	import {W, H, U, rng, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH,
3	  CLAWD_PARTS, TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';
4	
5	const PX = W * U, PY = H * U;
6	const r = rng(7741);
7	const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
8	
9	// 把多边形扫描成一组平行线段，线段就是一笔一笔的蜡笔排线。
10	function hatchSpans(points, angle, gap) {
11	  const a = angle * Math.PI / 180, cos = Math.cos(a), sin = Math.sin(a);
12	  const rot = points.map(([x, y]) => [x * cos + y * sin, -x * sin + y * cos]);
13	  const vs = rot.map(p => p[1]), spans = [];
14	  for (let v = Math.min(...vs) + gap * 0.4; v < Math.max(...vs); v += gap * (0.8 + r() * 0.4)) {
15	    const hits = [];
16	    rot.forEach(([x0, y0], i) => {
17	      const [x1, y1] = rot[(i + 1) % rot.length];
18	      if ((y0 <= v) !== (y1 <= v)) hits.push(x0 + (v - y0) * (x1 - x0) / (y1 - y0));
19	    });
20	    hits.sort((p, q) => p - q);
21	    for (let k = 0; k + 1 < hits.length; k += 2) {
22	      spans.push([[hits[k], v], [hits[k + 1], v]].map(([u, w]) => [u * cos - w * sin, u * sin + w * cos]));
23	    }
24	  }
25	  return spans;
26	}
27	
28	// 蜡笔不能盖住底色，所以先给后画的物体留出纸白：reserved(x, y) 为真的位置不下笔。
29	function splitAround(span, reserved) {
30	  const [[x0, y0], [x1, y1]] = span, len = Math.hypot(x1 - x0, y1 - y0), n = Math.ceil(len / 8), out = [];
31	  let start = null;
32	  for (let i = 0; i <= n; i++) {
33	    const t = i / n, x = x0 + (x1 - x0) * t, y = y0 + (y1 - y0) * t, free = !reserved(x / U, y / U);
34	    if (free && !start) start = [x, y];
35	    if (start && (!free || i === n)) { out.push([start, [x, y]]); start = null; }
36	  }
37	  return out;
38	}
39	
40	function scribble(points, color, {angle = 20, gap = 9, weight = 1, over = 3, alpha = 1, wob = 3, reserved = null, passes = 2} = {}) {
41	  for (let pass = 1; pass < passes; pass++) scribble(points, color, {angle: angle + 7 * pass, gap, weight, over, alpha, wob, reserved, passes: 1});
42	  const px = points.map(([x, y]) => [x * U, y * U]);
43	  brush.set('wax', color, weight);
44	  let spans = hatchSpans(px, angle + (r() - 0.5) * 3, gap);
45	  if (reserved) spans = spans.flatMap(s => splitAround(s, reserved));
46	  for (const [[x0, y0], [x1, y1]] of spans) {
47	    const len = Math.hypot(x1 - x0, y1 - y0);
48	    if (len < 2) continue;
49	    const ox = (x1 - x0) / len * (r() - 0.3) * over, oy = (y1 - y0) / len * (r() - 0.3) * over;
50	    const mx = (x0 + x1) / 2 + (r() - 0.5) * wob, my = (y0 + y1) / 2 + (r() - 0.5) * wob;
51	    if (len < 40) brush.line(x0 - ox, y0 - oy, x1 + ox, y1 + oy);
52	    else brush.spline([[x0 - ox, y0 - oy, 0.75 * alpha], [mx, my, alpha], [x1 + ox, y1 + oy, 0.8 * alpha]], 0.5);
53	  }
54	}
55	
56	function outline(points, color, weight = 0.5, name = 'wax', closed = true) {
57	  brush.set(name, color, weight);
58	  const pts = closed ? [...points, points[0]] : points;
59	  for (let i = 1; i < pts.length; i++) {
60	    const j = 1.6;
61	    brush.line(pts[i - 1][0] * U + (r() - 0.5) * j, pts[i - 1][1] * U + (r() - 0.5) * j, pts[i][0] * U + (r() - 0.5) * j, pts[i][1] * U + (r() - 0.5) * j);
62	  }
63	}
64	
65	const inTower = (x, y) => y >= TOWER.top - 1 && y <= TOWER.base && Math.abs(x - TOWER.cx) <= towerHalf(y) + 1.2 && Math.abs(x - TOWER.cx) >= towerArch(y) - 0.5;
66	const inSun = (x, y) => Math.hypot(x - SUN.x, y - SUN.y) <= SUN.r + 0.5;
67	const inBox = (x, y, [bx, by, bw, bh], m = 1) => x >= bx - m && x <= bx + bw + m && y >= by - m && y <= by + bh + m;
68	const inFront = (x, y) => inBox(x, y, CLAWD_PARTS.body) || inBox(x, y, CLAWD_PARTS.arm) || inBox(x, y, CLAWD_PARTS.armBack)
69	  || inBox(x, y, [BENCH.x, BENCH.top, BENCH.w, BENCH.h]) || inBox(x, y, [177, 137, 25, 6]);
70	const inFloorThings = (x, y) => inBox(x, y, [BENCH.x, BENCH.top, BENCH.w, BENCH.h]) || BENCH.legs.some(l => inBox(x, y, l)) || inBox(x, y, BENCH.brace)
71	  || inBox(x, y, SUITCASE.body) || CLAWD_PARTS.legs.some(l => inBox(x, y, l));
72	
73	// 一笔一笔地铺大面积，长度、角度、粗细都随机，避免规则条纹。
74	function freehand(top, bottom, count, colorAt, reserved) {
75	  for (let i = 0; i < count; i++) {
76	    const x = r() * (PX + 300) - 150, y = (top + r() * (bottom - top)) * U;
77	    const len = 150 + r() * 420, a = (-6 + r() * 7) * Math.PI / 180;
78	    const span = [[x, y], [x + Math.cos(a) * len, y + Math.sin(a) * len]];
79	    brush.set('wax', colorAt(y / U), 2.4 + r() * 2.2);
80	    for (const [[x0, y0], [x1, y1]] of splitAround(span, reserved)) {
81	      if (Math.hypot(x1 - x0, y1 - y0) < 8) continue;
82	      brush.spline([[x0, y0, 0.7], [(x0 + x1) / 2 + (r() - 0.5) * 8, (y0 + y1) / 2 + (r() - 0.5) * 10, 1], [x1, y1, 0.75]], 0.5);
83	    }
84	  }
85	}
86	
87	function paint() {
88	  // 天空：长短不一的手涂短排线，颜色随高度渐变，笔与笔之间露出纸面。
89	  const SKY = ['#c9dcdd', '#deeae0', '#f8f2d8', '#fef4d2', '#fee5bf', '#fbd0a6'];
90	  freehand(0, 147, 1250, y => SKY[Math.round(Math.min(1, Math.max(0, y / 122 + (r() - 0.5) * 0.14)) * (SKY.length - 1))],
91	    (x, y) => inTower(x, y) || inSun(x, y));
92	
93	  const sun = Array.from({length: 28}, (_, i) => [SUN.x + Math.cos(i / 28 * 6.283) * SUN.r, SUN.y + Math.sin(i / 28 * 6.283) * SUN.r]);
94	  scribble(sun, '#f9dc82', {angle: 30, gap: 4.5, weight: 1.6, over: 1});
95	  scribble(sun, C.sun, {angle: -40, gap: 8, weight: 1.2, over: 1});
96	
97	  for (const [x, y, size] of STARS) {
98	    const a = (1.5 + size * 1.4) * U;
99	    brush.set('wax', '#dd9226', 0.9 + size * 0.3);
100	    brush.line(x * U - a, y * U, x * U + a, y * U);
101	    brush.line(x * U, y * U - a, x * U, y * U + a);
102	  }
103	
104	  scribble(skylinePolygon(SKYLINE.far), '#e0d3b8', {angle: 88, gap: 6, weight: 1.6, over: 2, reserved: inTower});
105	  scribble(skylinePolygon(SKYLINE.mid), '#c1cdc5', {angle: 80, gap: 5, weight: 1.7, over: 2, reserved: inTower});
106	  scribble(skylinePolygon(SKYLINE.mid), '#a9b9b3', {angle: 62, gap: 18, weight: 1.1, over: 2, reserved: inTower});
107	  outline(skylinePolygon(SKYLINE.mid).slice(1, -1), '#90a29f', 0.8, 'wax', false);
108	  for (const l of SKYLINE.mid.lights) {
109	    brush.set('wax', l.warm ? '#f3cf74' : C.far, 0.8);
110	    brush.line(l.x * U, l.y * U, l.x * U + 5, l.y * U + 1);
111	  }
112	
113	  // 铁塔分色涂满再压桁架，塔身是全图唯一接近满涂的地方。
114	  for (const [a, b, key] of TOWER.bands) {
115	    const rows = [];
116	    for (let y = a; y <= b; y++) rows.push(y);
117	    const leftSide = rows.map(y => [TOWER.cx - towerHalf(y), y]);
118	    const rightSide = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
119	    if (a >= 117) {
120	      const lo = rows.map(y => [TOWER.cx - towerHalf(y), y]), inL = rows.slice().reverse().map(y => [TOWER.cx - Math.max(towerArch(y), 0.1), y]);
121	      const inR = rows.map(y => [TOWER.cx + Math.max(towerArch(y), 0.1), y]), ro = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
122	      for (const leg of [[...lo, ...inL], [...inR, ...ro]]) {
123	        scribble(leg, '#e26f4d', {angle: 70, gap: 2.6, weight: 1.1, over: 1, wob: 1});
124	      }
125	      continue;
126	    }
127	    const band = [...leftSide, ...rightSide];
128	    const color = key === 'red' ? C.red : C.white;
129	    scribble(band, key === 'red' ? '#e26f4d' : color, {angle: 72, gap: key === 'red' ? 2.6 : 5, weight: 1, over: 1, wob: 1});
130	    if (key === 'white') scribble(band, '#c9b99d', {angle: -50, gap: 11, weight: 0.8, over: 1, wob: 1});
131	  }
132	  for (let y = 58; y < TOWER.base - 6; y += 6) {
133	    if (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) continue;
134	    const h1 = towerHalf(y), h2 = towerHalf(y + 6), red = TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] === 'red';
135	    brush.set('wax', red ? '#7f2d1f' : '#8f8169', 0.9);
136	    brush.line((TOWER.cx - h1) * U, y * U, (TOWER.cx + h2) * U, (y + 6) * U);
137	    brush.line((TOWER.cx + h1) * U, y * U, (TOWER.cx - h2) * U, (y + 6) * U);
138	  }
139	  const edgeL = [], edgeR = [];
140	  for (let y = TOWER.top; y <= 128; y += 2) { edgeL.push([TOWER.cx - towerHalf(y), y]); edgeR.push([TOWER.cx + towerHalf(y), y]); }
141	  outline(edgeL, '#7f2d1f', 1.6, 'wax', false);
142	  outline(edgeR, '#7f2d1f', 1.6, 'wax', false);
143	  for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
144	    outline(rect(TOWER.cx - half, a, half * 2, b - a), '#6d4a3c', 1.6);
145	    brush.set('wax', C.rail, 1);
146	    for (let x = TOWER.cx - half + 1; x < TOWER.cx + half - 0.5; x += 2) brush.line(x * U, (a + 1) * U, x * U + 3, (a + 2) * U);
147	  }
148	
149	  scribble(skylinePolygon(SKYLINE.near), '#a4b7ba', {angle: 76, gap: 4, weight: 2, over: 2, reserved: inFront});
150	  scribble(skylinePolygon(SKYLINE.near), '#8ca2a8', {angle: 52, gap: 12, weight: 1.4, over: 2, reserved: inFront});
151	  outline(skylinePolygon(SKYLINE.near).slice(1, -1), C.rail, 1.1, 'wax', false);
152	  for (const l of SKYLINE.near.lights) {
153	    brush.set('wax', '#f1b73f', 1.2);
154	    brush.line(l.x * U, l.y * U, l.x * U + 9, l.y * U + 1);
155	    brush.line(l.x * U + 1, l.y * U + 4, l.x * U + 8, l.y * U + 4);
156	  }
157	
158	  brush.set('wax', C.rail, 1.9);
159	  brush.spline([[-20, RAIL.top * U + 2], [PX / 2, RAIL.top * U - 3], [PX + 20, RAIL.top * U + 2]], 0.3);
160	  brush.set('wax', C.nearDark, 1.3);
161	  brush.spline([[-20, RAIL.low * U], [PX / 2, RAIL.low * U + 3], [PX + 20, RAIL.low * U - 1]], 0.3);
162	  for (const x of RAIL.posts) {
163	    brush.set('wax', C.rail, 1.5);
164	    brush.line(x * U, RAIL.top * U, x * U + (r() - 0.5) * 3, RAIL.wall * U);
165	  }
166	  scribble(rect(-4, RAIL.wall, W + 8, RAIL.floor - RAIL.wall), '#88a0a6', {angle: 8, gap: 4, weight: 1.5, over: 6, reserved: inFront});
167	
168	  freehand(RAIL.floor + 1, H + 2, 520, () => (r() < 0.72 ? '#ecdab2' : '#dcc698'), (x, y) => y < RAIL.floor || inFloorThings(x, y));
169	  for (const shade of [SHADOW, CASE_SHADOW]) scribble(shade, '#b5a58a', {angle: 32, gap: 5, weight: 1.7, over: 2});
170	
171	  for (const leg of BENCH.legs) {
172	    scribble(rect(...leg), C.branch, {angle: 84, gap: 2.2, weight: 1.1, over: 1, wob: 1});
173	  }
174	  scribble(rect(...BENCH.brace), C.woodDark, {angle: 2, gap: 2.5, weight: 1, over: 2, wob: 1});
175	
176	  const c = SUITCASE;
177	  outline([[c.handle[0], c.body[1]], [c.handle[0], c.handle[1]], [c.handle[0] + c.handle[2], c.handle[1]], [c.handle[0] + c.handle[2], c.body[1]]], C.branch, 1.6, 'wax', false);
178	  scribble(rect(...c.body), '#8fafa5', {angle: 75, gap: 3, weight: 1.6, over: 1, wob: 2});
179	  scribble(rect(c.body[0] + c.body[2] - 4, c.body[1], 4, c.body[3]), '#6f9087', {angle: 70, gap: 2.8, weight: 1.1, over: 1, wob: 1});
180	  for (const s of c.straps) { brush.set('wax', C.white, 0.9); brush.line(s[0] * U + 3, s[1] * U, s[0] * U + 3, (s[1] + s[3]) * U); }
181	  outline(rect(...c.body), '#3f5650', 1.5);
182	
183	  // 主角按 32 格比例重画，涂得最满最深，是画面视线的落点。
184	  const p = CLAWD_PARTS;
185	  for (const leg of p.legs) scribble(rect(...leg), '#a84f3c', {angle: 88, gap: 2.2, weight: 1, over: 1, wob: 1});
186	
187	  scribble(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), '#cda172', {angle: 3, gap: 3, weight: 1.5, over: 5, wob: 2});
188	  scribble(rect(BENCH.x, BENCH.top + 3, BENCH.w, 2), '#a87d57', {angle: 1, gap: 2.5, weight: 1, over: 3, wob: 1});
189	  outline(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), '#5c3f2e', 1.6);
190	  for (const leg of p.legs) scribble(rect(leg[0], leg[1] + 1, leg[2], 5), '#a84f3c', {angle: 88, gap: 2.2, weight: 1, over: 1, wob: 1});
191	
192	  scribble(rect(...p.armBack), '#a84f3c', {angle: 10, gap: 2.4, weight: 1, over: 1, wob: 1});
193	  scribble(rect(...p.body), '#e58a68', {angle: 58, gap: 2.8, weight: 1.8, over: 1, wob: 2});
194	  scribble(rect(...p.body), '#d97c5a', {angle: -38, gap: 7, weight: 1.2, over: 1, wob: 2});
195	  scribble(rect(p.body[0], p.body[1] + 2, 3, p.body[3] - 2), '#a84f3c', {angle: 80, gap: 2.4, weight: 1, over: 1, wob: 1});
196	  scribble(rect(p.body[0] + 2, p.body[1], p.body[2] - 3, 1.5), '#f0a57f', {angle: 2, gap: 2.4, weight: 1, over: 1, wob: 1});
197	  outline(rect(...p.body), '#713f32', 2);
198	  scribble(rect(...p.arm), '#ed9b75', {angle: 10, gap: 2.2, weight: 1, over: 1, wob: 1});
199	  outline(rect(...p.arm), '#713f32', 1.6);
200	  scribble(rect(...p.eye), '#352e2a', {angle: 85, gap: 1.6, weight: 0.9, over: 0.5, wob: 0.5});
201	
202	  TICKETS.forEach((t, i) => {
203	    scribble(t, C.white, {angle: 10, gap: 2.4, weight: 1, over: 1, wob: 1});
204	    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
205	    scribble(rect(stub, Math.max(t[0][1], t[1][1]) + 0.3, 2, 4), C.red, {angle: 85, gap: 2, weight: 1, over: 0.5, wob: 1});
206	    outline(t, '#6d4a3c', 1.3);
207	  });
208	
