input.content:
import {W, H, U, rng, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH,
  CLAWD_PARTS, TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const PX = W * U, PY = H * U;
const CORE = '#fbf5e6';
const r = rng(5170);
const scale = pts => pts.map(([x, y]) => [x * U, y * U]);
const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];

// 沿边重采样并加噪声：撕纸用多尺度起伏，剪纸只留微小手抖。
function roughen(pts, step, amp) {
  const out = [];
  let slow = r() * 6, fast = r() * 6;
  pts.forEach(([x, y], i) => {
    const [nx, ny] = pts[(i + 1) % pts.length], len = Math.hypot(nx - x, ny - y) || 1, n = Math.max(1, Math.ceil(len / step));
    for (let j = 0; j < n; j++) {
      slow += 0.22 + r() * 0.1; fast += 0.9 + r() * 0.6;
      const d = (Math.sin(slow) * 0.6 + Math.sin(fast) * 0.3 + (r() - 0.5) * 0.5) * amp, t = j / n;
      out.push([x + (nx - x) * t - (ny - y) / len * d, y + (ny - y) * t + (nx - x) / len * d]);
    }
  });
  return out;
}

function makeTexture(paint, w = 720, h = 720) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  paint(c.getContext('2d'), w, h);
  return c;
}
const fibre = makeTexture((t, w, h) => {
  t.fillStyle = '#fff'; t.fillRect(0, 0, w, h);
  for (let i = 0; i < 90; i++) {
    t.fillStyle = `rgba(120,100,70,${0.012 + r() * 0.03})`;
    t.beginPath(); t.ellipse(r() * w, r() * h, 25 + r() * 80, 18 + r() * 60, r() * 3, 0, 7); t.fill();
  }
  for (let i = 0; i < 2600; i++) {
    const x = r() * w, y = r() * h, a = r() * 6.3, l = 3 + r() * 14;
    t.strokeStyle = r() < 0.72 ? `rgba(90,70,45,${0.05 + r() * 0.12})` : 'rgba(255,255,255,.5)';
    t.lineWidth = 0.4 + r() * 0.7;
    t.beginPath(); t.moveTo(x, y); t.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); t.stroke();
  }
});
const kraft = makeTexture((t, w, h) => {
  t.fillStyle = '#c4a176'; t.fillRect(0, 0, w, h);
  for (let i = 0; i < 6500; i++) {
    const x = r() * w, y = r() * h, l = 6 + r() * 24;
    t.strokeStyle = r() < 0.55 ? `rgba(95,66,36,${0.08 + r() * 0.2})` : `rgba(240,215,175,${0.1 + r() * 0.22})`;
    t.lineWidth = 0.4 + r() * 0.8;
    t.beginPath(); t.moveTo(x, y); t.lineTo(x + l, y + (r() - 0.5) * 5); t.stroke();
  }
});
// 旧报纸：只有灰色的假字条与半调方块，没有可读文字。
const news = makeTexture((t, w, h) => {
  t.fillStyle = '#eadfc8'; t.fillRect(0, 0, w, h);
  const cols = 5, cw = w / cols;
  for (let c = 0; c < cols; c++) {
    const x = c * cw + 10;
    for (let y = 8; y < h; y += 9) {
      if (c === 1 && y > 180 && y < 320) continue;
      let px = x;
      const end = x + cw - 20;
      while (px < end) {
        const len = 3 + r() * 13;
        t.fillStyle = `rgba(62,56,48,${0.42 + r() * 0.3})`;
        t.fillRect(px, y, Math.min(len, end - px), 3);
        px += len + 2.5;
      }
    }
  }
  t.fillStyle = 'rgba(62,56,48,.55)';
  for (let y = 184; y < 316; y += 5) for (let x = cw + 12; x < 2 * cw - 12; x += 5) {
    t.beginPath(); t.arc(x, y, 0.8 + 1.5 * Math.abs(Math.sin(x / 26 + y / 40)), 0, 7); t.fill();
  }
}, 900, 720);

export function drawPaper() {
  const canvas = document.createElement('canvas');
  canvas.width = PX; canvas.height = PY; document.body.append(canvas);
  const ctx = canvas.getContext('2d');
  const trace = pts => { ctx.beginPath(); pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); ctx.closePath(); };
  const overlay = (tex, mode = 'multiply') => {
    ctx.globalCompositeOperation = mode;
    ctx.fillStyle = ctx.createPattern(tex, 'repeat');
    ctx.fillRect(0, 0, PX, PY);
    ctx.globalCompositeOperation = 'source-over';
  };

  // 一张纸片：先画带投影的白色纸芯或白边，再把上色面叠上去并压纹理。
  function piece(points, {color, edge = 'cut', border = 7, lift = 1, tex = null, detail = null}) {
    const base = scale(points);
    const outer = edge === 'torn' ? roughen(base, 7, 7) : roughen(base, 34, 0.9);
    const inner = edge === 'torn' ? roughen(base, 7, 3.5) : outer;
    ctx.save();
    ctx.shadowColor = 'rgba(58,42,24,.42)'; ctx.shadowBlur = 7 + lift * 7; ctx.shadowOffsetX = 2 + lift * 2; ctx.shadowOffsetY = 3 + lift * 4;
    trace(outer);
    ctx.fillStyle = CORE; ctx.fill();
    if (edge === 'cut' && border) { ctx.strokeStyle = CORE; ctx.lineWidth = border; ctx.lineJoin = 'round'; ctx.stroke(); }
    ctx.restore();
    ctx.save();
    trace(inner); ctx.clip();
    if (tex) { ctx.fillStyle = ctx.createPattern(tex, 'repeat'); ctx.fillRect(0, 0, PX, PY); }
    if (color) {
      ctx.globalCompositeOperation = tex ? 'multiply' : 'source-over';
      ctx.fillStyle = color; ctx.fillRect(0, 0, PX, PY);
      ctx.globalCompositeOperation = 'source-over';
    }
    overlay(fibre);
    detail?.();
    ctx.restore();
  }
  const stripe = (pts, color, width, border = 4) => {
    const line = scale(pts);
    ctx.save();
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    ctx.shadowColor = 'rgba(58,42,24,.4)'; ctx.shadowBlur = 7; ctx.shadowOffsetX = 2; ctx.shadowOffsetY = 4;
    const path = () => { ctx.beginPath(); line.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); };
    path(); ctx.strokeStyle = CORE; ctx.lineWidth = width + border; ctx.stroke();
    ctx.shadowColor = 'transparent';
    path(); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
    ctx.restore();
  };

  // 牛皮纸底，四边露出，天空是三张撕开的色纸。
  ctx.fillStyle = ctx.createPattern(kraft, 'repeat'); ctx.fillRect(0, 0, PX, PY);
  piece([[3, 62], [317, 58], [316, 148], [4, 148]], {color: '#f3c99c', edge: 'torn', lift: 0.6});
  piece([[4, 30], [316, 27], [317, 72], [210, 80], [110, 72], [4, 78]], {color: '#f2e6c8', edge: 'torn', lift: 0.8});
  piece([[3, 3], [317, 4], [316, 34], [230, 41], [120, 33], [3, 42]], {color: '#b4c9ca', edge: 'torn', lift: 1});

  piece(Array.from({length: 40}, (_, i) => [SUN.x + Math.cos(i / 40 * 6.283) * SUN.r, SUN.y + Math.sin(i / 40 * 6.283) * SUN.r]), {color: '#f9dd8e', lift: 0.7});
  for (const [x, y, size] of STARS) {
    const a = 1.6 + size * 1.5, b = a * 0.3;
    piece([[x, y - a], [x + b, y - b], [x + a, y], [x + b, y + b], [x, y + a], [x - b, y + b], [x - a, y], [x - b, y - b]], {color: C.lamp, border: 4, lift: 0.3});
  }

  // 远景是撕开的旧报纸，中景是一栋栋微斜的色纸。
  piece(skylinePolygon(SKYLINE.far), {tex: news, color: '#efe2c9', edge: 'torn', lift: 0.8});
  const building = (b, color, lift, bottom = 147) => {
    const tilt = (r() - 0.5) * 0.9;
    piece([[b.x, b.top + tilt], [b.x + b.w, b.top - tilt], [b.x + b.w + tilt, bottom], [b.x, bottom]], {color, border: 3.5, lift});
  };
  SKYLINE.mid.buildings.forEach((b, i) => building(b, i % 2 ? C.mid : '#a9b6b0', 0.5));
  for (const l of SKYLINE.mid.lights) {
    ctx.fillStyle = l.warm ? C.sun : CORE; ctx.fillRect(l.x * U, l.y * U, 7, 8);
  }

  // 铁塔：外轮廓一刀剪下，再按高度分色，桁架用细线压在纸面上。
  const left = [], right = [];
  for (let y = TOWER.top; y <= TOWER.base; y++) { left.push([TOWER.cx - towerHalf(y), y]); right.unshift([TOWER.cx + towerHalf(y), y]); }
  const archPts = [];
  for (let y = TOWER.base; y >= 117; y--) archPts.push([TOWER.cx - towerArch(y), y]);
  for (let y = 117; y <= TOWER.base; y++) archPts.push([TOWER.cx + towerArch(y), y]);
  const towerOutline = [...left, ...archPts, ...right.slice(0)];
  piece(towerOutline, {color: C.white, border: 6, lift: 1.2, detail: () => {
    for (const [a, b, key] of TOWER.bands) {
      if (key !== 'red') continue;
      ctx.fillStyle = C.red; ctx.fillRect(0, a * U, PX, (b - a) * U);
    }
    ctx.lineCap = 'round';
    for (let y = 58; y < TOWER.base; y += 6) {
      if (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) continue;
      const h1 = towerHalf(y), h2 = towerHalf(y + 6);
      const dark = TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] === 'red' ? C.redDark : '#b9ac94';
      ctx.strokeStyle = dark; ctx.lineWidth = 3;
      const seg = (x1, y1, x2, y2) => { ctx.beginPath(); ctx.moveTo(x1 * U, y1 * U); ctx.lineTo(x2 * U, y2 * U); ctx.stroke(); };
      seg(TOWER.cx - h1, y, TOWER.cx + h2, y + 6); seg(TOWER.cx + h1, y, TOWER.cx - h2, y + 6);
      seg(TOWER.cx - h1, y, TOWER.cx + h1, y);
    }
  }});
  for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
    piece(rect(TOWER.cx - half, a, half * 2, b - a), {color: C.white, border: 4, lift: 0.7, detail: () => {
      ctx.fillStyle = C.rail;
      for (let x = TOWER.cx - half + 1; x < TOWER.cx + half - 0.5; x += 2) ctx.fillRect(x * U, (a + 1) * U, 5, 8);
      ctx.fillStyle = C.redDark; ctx.fillRect(0, (b - 1) * U, PX, U);
    }});
  }

  SKYLINE.near.buildings.forEach((b, i) => building(b, i % 3 === 0 ? C.nearDark : C.near, 0.7));
  for (const l of SKYLINE.near.lights) {
    ctx.save();
    ctx.shadowColor = 'rgba(40,40,30,.35)'; ctx.shadowBlur = 2; ctx.shadowOffsetY = 1;
    ctx.fillStyle = l.warm ? C.lamp : C.sun; ctx.fillRect(l.x * U, l.y * U, 10, 8);
    ctx.restore();
  }

  stripe([[-2, RAIL.low], [W + 2, RAIL.low]], C.nearDark, 5, 3);
  for (const x of RAIL.posts) stripe([[x, RAIL.top], [x, RAIL.wall]], C.rail, 6, 3);
  stripe([[-2, RAIL.top], [W + 2, RAIL.top]], C.rail, 8, 3);
  piece([[-3, RAIL.wall], [W + 3, RAIL.wall], [W + 3, RAIL.floor + 3], [-3, RAIL.floor + 3]], {color: C.nearDark, edge: 'torn', lift: 0.9});

  // 地面用同一张牛皮纸的另一块，地缝是撕痕的阴影。
  piece([[-4, RAIL.floor], [W + 4, RAIL.floor], [W + 4, H + 4], [-4, H + 4]], {tex: kraft, color: '#f3e1bd', edge: 'torn', lift: 1.2, detail: () => {
    ctx.strokeStyle = 'rgba(90,66,40,.2)'; ctx.lineWidth = 3;
    for (const y of [152, 160, 171]) { ctx.beginPath(); ctx.moveTo(0, y * U); ctx.lineTo(PX, y * U + (r() - 0.5) * 8); ctx.stroke(); }
  }});
  for (const shade of [SHADOW, CASE_SHADOW]) {
    trace(roughen(scale(shade), 14, 2)); ctx.fillStyle = 'rgba(84,62,42,.3)'; ctx.fill();
  }

  for (const [x, y, w, h] of BENCH.legs) piece(rect(x, y, w, h), {color: C.branch, border: 5, lift: 0.8});
  piece(rect(...BENCH.brace), {color: C.woodDark, border: 4, lift: 0.5});
  const c = SUITCASE;
  stripe([[c.handle[0], c.body[1]], [c.handle[0], c.handle[1]], [c.handle[0] + c.handle[2], c.handle[1]], [c.handle[0] + c.handle[2], c.body[1]]], C.branch, 6, 3);
  piece(rect(...c.body), {color: C.caseBody, lift: 1.1, detail: () => {
    ctx.fillStyle = C.caseDark; ctx.fillRect((c.body[0] + c.body[2] - 3) * U, 0, 3 * U, PY);
  }});
  for (const s of c.straps) piece(rect(...s), {color: C.whiteDark, border: 2, lift: 0.2});

  piece(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), {color: C.wood, lift: 1.2, detail: () => {
    for (let i = 0; i < 26; i++) {
      const y = (BENCH.top + r() * BENCH.h) * U, x = (BENCH.x + r() * BENCH.w * 0.8) * U;
      ctx.strokeStyle = 'rgba(92,62,38,.4)'; ctx.lineWidth = 1 + r() * 1.5;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.bezierCurveTo(x + 40, y + 2, x + 80, y - 2, x + 90 + r() * 70, y + 1); ctx.stroke();
    }
  }});

  // 主角：与像素版同比例的一组纸片，侧身望向左侧。
  const p = CLAWD_PARTS;
  piece(rect(...p.armBack), {color: '#b85d47', border: 5, lift: 0.5});
  for (const leg of p.legs) piece(rect(...leg), {color: '#b85d47', border: 4, lift: 0.5});
  piece(rect(...p.body), {color: '#da7758', lift: 1.5, detail: () => {
    ctx.fillStyle = '#b85d47'; ctx.fillRect((p.body[0]) * U, 0, 2.2 * U, PY); // 背光面在远离太阳一侧
    ctx.fillStyle = '#ed9b75'; ctx.fillRect(p.body[0] * U, p.body[1] * U, p.body[2] * U, 1.3 * U);
  }});
  piece(rect(...p.arm), {color: '#ed9b75', border: 5, lift: 0.8});
  piece(rect(...p.eye), {color: '#352e2a', border: 3, lift: 0.2});
  piece(rect(...p.tear), {color: '#83bdcf', border: 2.5, lift: 0.2});

  TICKETS.forEach((t, i) => piece(t, {color: C.white, border: 4, lift: 0.8, detail: () => {
    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
    ctx.fillStyle = C.red; ctx.fillRect(stub * U, 0, 2 * U, PY);
  }}));

  for (const pts of BRANCH) stripe(pts, C.branch, 7, 4);
  LEAVES.forEach(([x, y], i) => {
    const s = leafShape(x, y, i % 2 ? 1 : -1).map(([a, b]) => [x + (a - x) * 1.25, y + (b - y) * 1.25]);
    piece(s, {color: i % 3 === 0 ? C.leafDark : C.leaf, border: 3, lift: 0.6});
  });

  return {canvas};
}

/* global p5, brush */
import {W, H, U, rng, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH,
  CLAWD_PARTS, TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const PX = W * U, PY = H * U;
const r = rng(7741);
const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];

// 把多边形扫描成一组平行线段，线段就是一笔一笔的蜡笔排线。
function hatchSpans(points, angle, gap) {
  const a = angle * Math.PI / 180, cos = Math.cos(a), sin = Math.sin(a);
  const rot = points.map(([x, y]) => [x * cos + y * sin, -x * sin + y * cos]);
  const vs = rot.map(p => p[1]), spans = [];
  for (let v = Math.min(...vs) + gap * 0.4; v < Math.max(...vs); v += gap * (0.8 + r() * 0.4)) {
    const hits = [];
    rot.forEach(([x0, y0], i) => {
      const [x1, y1] = rot[(i + 1) % rot.length];
      if ((y0 <= v) !== (y1 <= v)) hits.push(x0 + (v - y0) * (x1 - x0) / (y1 - y0));
    });
    hits.sort((p, q) => p - q);
    for (let k = 0; k + 1 < hits.length; k += 2) {
      spans.push([[hits[k], v], [hits[k + 1], v]].map(([u, w]) => [u * cos - w * sin, u * sin + w * cos]));
    }
  }
  return spans;
}

function scribble(points, color, {angle = 20, gap = 9, weight = 1, over = 3, alpha = 1, wob = 3} = {}) {
  const px = points.map(([x, y]) => [x * U, y * U]);
  brush.set('crayon', color, weight);
  for (const [[x0, y0], [x1, y1]] of hatchSpans(px, angle + (r() - 0.5) * 3, gap)) {
    const len = Math.hypot(x1 - x0, y1 - y0);
    if (len < 2) continue;
    const ox = (x1 - x0) / len * (r() - 0.3) * over, oy = (y1 - y0) / len * (r() - 0.3) * over;
    const mx = (x0 + x1) / 2 + (r() - 0.5) * wob, my = (y0 + y1) / 2 + (r() - 0.5) * wob;
    if (len < 40) brush.line(x0 - ox, y0 - oy, x1 + ox, y1 + oy);
    else brush.spline([[x0 - ox, y0 - oy, 0.75 * alpha], [mx, my, alpha], [x1 + ox, y1 + oy, 0.8 * alpha]], 0.5);
  }
}

function outline(points, color, weight = 0.5, name = '2B', closed = true) {
  brush.set(name, color, weight);
  const pts = closed ? [...points, points[0]] : points;
  for (let i = 1; i < pts.length; i++) {
    const j = 1.6;
    brush.line(pts[i - 1][0] * U + (r() - 0.5) * j, pts[i - 1][1] * U + (r() - 0.5) * j, pts[i][0] * U + (r() - 0.5) * j, pts[i][1] * U + (r() - 0.5) * j);
  }
}

function paint() {
  // 天空：从上到下换色长排线，故意留白露出纸面。
  const bands = [[-6, 34, C.sky[0]], [24, 58, C.sky[1]], [48, 82, C.sky[2]], [72, 102, C.sky[3]], [92, 120, C.sky[4]], [108, 147, C.sky[5]]];
  for (const [a, b, color] of bands) {
    scribble(rect(-6, a, W + 12, b - a), color, {angle: -5, gap: 21, weight: 3.8, over: 30, wob: 20});
  }

  const sun = Array.from({length: 28}, (_, i) => [SUN.x + Math.cos(i / 28 * 6.283) * SUN.r, SUN.y + Math.sin(i / 28 * 6.283) * SUN.r]);
  scribble(sun, '#f8d978', {angle: 30, gap: 7, weight: 1.5, over: 1});
  scribble(sun, C.sun, {angle: -40, gap: 12, weight: 1.2, over: 1});

  for (const [x, y, size] of STARS) {
    const a = (1.5 + size * 1.4) * U;
    brush.set('crayon', '#e29f35', 0.7 + size * 0.3);
    brush.line(x * U - a, y * U, x * U + a, y * U);
    brush.line(x * U, y * U - a, x * U, y * U + a);
  }

  scribble(skylinePolygon(SKYLINE.far), C.far, {angle: 88, gap: 11, weight: 1.6, over: 2});
  scribble(skylinePolygon(SKYLINE.mid), C.mid, {angle: 80, gap: 10, weight: 1.7, over: 2});
  scribble(skylinePolygon(SKYLINE.mid), '#94a7a5', {angle: 62, gap: 34, weight: 1.1, over: 2});
  for (const l of SKYLINE.mid.lights) {
    brush.set('crayon', l.warm ? '#f3cf74' : C.far, 0.8);
    brush.line(l.x * U, l.y * U, l.x * U + 5, l.y * U + 1);
  }

  // 铁塔分色涂满再压桁架，塔身是全图唯一接近满涂的地方。
  for (const [a, b, key] of TOWER.bands) {
    const rows = [];
    for (let y = a; y <= b; y++) rows.push(y);
    const leftSide = rows.map(y => [TOWER.cx - towerHalf(y), y]);
    const rightSide = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
    if (a >= 117) {
      const lo = rows.map(y => [TOWER.cx - towerHalf(y), y]), inL = rows.slice().reverse().map(y => [TOWER.cx - Math.max(towerArch(y), 0.1), y]);
      const inR = rows.map(y => [TOWER.cx + Math.max(towerArch(y), 0.1), y]), ro = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
      for (const leg of [[...lo, ...inL], [...inR, ...ro]]) {
        scribble(leg, C.red, {angle: 70, gap: 4.5, weight: 1, over: 1, wob: 1});
      }
      continue;
    }
    const band = [...leftSide, ...rightSide];
    const color = key === 'red' ? C.red : C.white;
    scribble(band, color, {angle: 72, gap: key === 'red' ? 4.5 : 7, weight: b - a < 12 && a < 57 ? 0.8 : 1, over: 1, wob: 1});
    if (key === 'white') scribble(band, C.whiteDark, {angle: -50, gap: 14, weight: 0.7, over: 1, wob: 1});
  }
  for (let y = 58; y < TOWER.base - 6; y += 6) {
    if (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) continue;
    const h1 = towerHalf(y), h2 = towerHalf(y + 6), red = TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] === 'red';
    brush.set('2B', red ? '#8c3525' : '#a4977f', 0.55);
    brush.line((TOWER.cx - h1) * U, y * U, (TOWER.cx + h2) * U, (y + 6) * U);
    brush.line((TOWER.cx + h1) * U, y * U, (TOWER.cx - h2) * U, (y + 6) * U);
  }
  const edgeL = [], edgeR = [];
  for (let y = TOWER.top; y <= 128; y += 2) { edgeL.push([TOWER.cx - towerHalf(y), y]); edgeR.push([TOWER.cx + towerHalf(y), y]); }
  outline(edgeL, '#8c3525', 0.6, '2B', false);
  outline(edgeR, '#8c3525', 0.6, '2B', false);
  for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
    scribble(rect(TOWER.cx - half, a, half * 2, b - a), C.white, {angle: 5, gap: 5, weight: 1, over: 1, wob: 1});
    outline(rect(TOWER.cx - half, a, half * 2, b - a), '#6d4a3c', 0.6);
    brush.set('crayon', C.rail, 0.8);
    for (let x = TOWER.cx - half + 1; x < TOWER.cx + half - 0.5; x += 2) brush.line(x * U, (a + 1) * U, x * U + 3, (a + 2) * U);
  }

  scribble(skylinePolygon(SKYLINE.near), C.near, {angle: 76, gap: 7.5, weight: 1.9, over: 2});
  scribble(skylinePolygon(SKYLINE.near), C.nearDark, {angle: 52, gap: 19, weight: 1.3, over: 2});
  for (const l of SKYLINE.near.lights) {
    brush.set('crayon', l.warm ? C.lamp : C.sun, 1.1);
    brush.line(l.x * U, l.y * U, l.x * U + 9, l.y * U + 1);
    if (l.warm) brush.line(l.x * U + 1, l.y * U + 4, l.x * U + 8, l.y * U + 4);
  }

  brush.set('crayon', C.rail, 1.2);
  brush.spline([[-20, RAIL.top * U + 2], [PX / 2, RAIL.top * U - 3], [PX + 20, RAIL.top * U + 2]], 0.3);
  brush.set('crayon', C.nearDark, 0.8);
  brush.spline([[-20, RAIL.low * U], [PX / 2, RAIL.low * U + 3], [PX + 20, RAIL.low * U - 1]], 0.3);
  for (const x of RAIL.posts) {
    brush.set('crayon', C.rail, 0.9);
    brush.line(x * U, RAIL.top * U, x * U + (r() - 0.5) * 3, RAIL.wall * U);
  }
  scribble(rect(-4, RAIL.wall, W + 8, RAIL.floor - RAIL.wall), C.nearDark, {angle: 8, gap: 6, weight: 1.4, over: 6});

  scribble(rect(-4, RAIL.floor, W + 8, H - RAIL.floor + 4), C.floor, {angle: -7, gap: 13, weight: 3.2, over: 30, wob: 12});
  scribble([[-4, 158], [150, 150], [130, H + 4], [-4, H + 4]], C.floorDark, {angle: 20, gap: 22, weight: 2.4, over: 10, wob: 10});
  scribble([[250, RAIL.floor], [W + 4, RAIL.floor], [W + 4, H + 4], [270, H + 4]], C.floorDark, {angle: 20, gap: 26, weight: 2.2, over: 10, wob: 10});
  for (const shade of [SHADOW, CASE_SHADOW]) scribble(shade, '#a99a80', {angle: 32, gap: 8, weight: 1.7, over: 2});

  for (const leg of BENCH.legs) {
    scribble(rect(...leg), C.branch, {angle: 84, gap: 3.5, weight: 1, over: 1, wob: 1});
  }
  scribble(rect(...BENCH.brace), C.woodDark, {angle: 2, gap: 4, weight: 0.9, over: 2, wob: 1});

  const c = SUITCASE;
  outline([[c.handle[0], c.body[1]], [c.handle[0], c.handle[1]], [c.handle[0] + c.handle[2], c.handle[1]], [c.handle[0] + c.handle[2], c.body[1]]], C.branch, 1.1, 'crayon', false);
  scribble(rect(...c.body), C.caseBody, {angle: 75, gap: 5.5, weight: 1.5, over: 1, wob: 2});
  scribble(rect(c.body[0] + c.body[2] - 4, c.body[1], 4, c.body[3]), C.caseDark, {angle: 70, gap: 4.5, weight: 1, over: 1, wob: 1});
  for (const s of c.straps) { brush.set('crayon', C.white, 0.9); brush.line(s[0] * U + 3, s[1] * U, s[0] * U + 3, (s[1] + s[3]) * U); }
  outline(rect(...c.body), '#3f5650', 0.55);

  // 主角按 32 格比例重画，涂得最满最深，是画面视线的落点。
  const p = CLAWD_PARTS;
  for (const leg of p.legs) scribble(rect(...leg), '#a84f3c', {angle: 88, gap: 3.2, weight: 0.9, over: 1, wob: 1});

  scribble(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), C.wood, {angle: 3, gap: 5, weight: 1.5, over: 5, wob: 2});
  scribble(rect(BENCH.x, BENCH.top + 3, BENCH.w, 2), C.woodDark, {angle: 1, gap: 4, weight: 0.9, over: 3, wob: 1});
  outline(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), '#5c3f2e', 0.6);
  for (const leg of p.legs) scribble(rect(leg[0], leg[1] + 1, leg[2], 5), '#a84f3c', {angle: 88, gap: 3.2, weight: 0.9, over: 1, wob: 1});

  scribble(rect(...p.armBack), '#a84f3c', {angle: 10, gap: 4, weight: 1, over: 1, wob: 1});
  scribble(rect(...p.body), '#da7758', {angle: 58, gap: 5, weight: 1.7, over: 1, wob: 2});
  scribble(rect(...p.body), '#c9654a', {angle: -38, gap: 11, weight: 1.1, over: 1, wob: 2});
  scribble(rect(p.body[0], p.body[1] + 2, 3, p.body[3] - 2), '#a84f3c', {angle: 80, gap: 4, weight: 1, over: 1, wob: 1});
  scribble(rect(p.body[0] + 2, p.body[1], p.body[2] - 3, 1.5), '#f0a57f', {angle: 2, gap: 4, weight: 0.9, over: 1, wob: 1});
  outline(rect(...p.body), '#713f32', 0.75);
  scribble(rect(...p.arm), '#ed9b75', {angle: 10, gap: 3.5, weight: 1, over: 1, wob: 1});
  outline(rect(...p.arm), '#713f32', 0.6);
  scribble(rect(...p.eye), '#352e2a', {angle: 85, gap: 2.2, weight: 0.8, over: 0.5, wob: 0.5});
  brush.set('crayon', '#5da6bd', 0.8);
  brush.line((p.tear[0] + 0.5) * U, p.tear[1] * U, (p.tear[0] + 0.5) * U, (p.tear[1] + p.tear[3] + 1) * U);

  TICKETS.forEach((t, i) => {
    scribble(t, C.white, {angle: 10, gap: 4, weight: 1, over: 1, wob: 1});
    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
    scribble(rect(stub, Math.max(t[0][1], t[1][1]) + 0.3, 2, 4), C.red, {angle: 85, gap: 3, weight: 0.8, over: 0.5, wob: 1});
    outline(t, '#6d4a3c', 0.5);
  });

  for (const pts of BRANCH) outline(pts, C.branch, 1.25, 'crayon', false);
  LEAVES.forEach(([x, y], i) => {
    const s = leafShape(x, y, i % 2 ? 1 : -1).map(([a, b]) => [x + (a - x) * 1.25, y + (b - y) * 1.25]);
    scribble(s, i % 3 === 0 ? C.leafDark : C.leaf, {angle: 40 + i * 13, gap: 3.5, weight: 1, over: 1, wob: 1});
  });
}

export function drawCrayon(done) {
  new p5(p => {
    brush.instance(p);
    p.setup = () => {
      const cnv = p.createCanvas(PX, PY, p.WEBGL);
      p.pixelDensity(1); p.randomSeed(7741); p.noiseSeed(7741); p.angleMode(p.DEGREES);
      brush.scaleBrushes(3); p.noLoop();
      window.crayonSource = cnv.elt;
    };
    p.draw = () => {
      p.background('#f6efdf'); p.translate(-PX / 2, -PY / 2);
      brush.noField(); brush.noFill(); brush.noHatch();
      paint();
      requestAnimationFrame(() => {
        // 回到 2D 画布压上纸张纹理，纸面的纤维与颗粒透出每一笔。
        const out = document.createElement('canvas');
        out.width = PX; out.height = PY;
        const ctx = out.getContext('2d');
        ctx.drawImage(window.crayonSource, 0, 0, PX, PY);
        const tex = document.createElement('canvas');
        tex.width = 512; tex.height = 512;
        const t = tex.getContext('2d'), im = t.createImageData(512, 512);
        for (let i = 0; i < im.data.length; i += 4) {
          const v = r() > 0.5 ? 255 : 70;
          im.data[i] = im.data[i + 1] = im.data[i + 2] = v; im.data[i + 3] = r() * 42;
        }
        t.putImageData(im, 0, 0);
        ctx.fillStyle = ctx.createPattern(tex, 'repeat'); ctx.fillRect(0, 0, PX, PY);
        window.crayonSource.style.display = 'none';
        document.body.append(out);
        done({canvas: out, brushes: brush.box()});
      });
    };
  });
}

