import {drawCharacter} from '../../../assets/clawd/character.js';
import {isLit} from './clip.js';
import {W, H, U, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH,
  TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const BAYER = [[0, 32, 8, 40, 2, 34, 10, 42], [48, 16, 56, 24, 50, 18, 58, 26], [12, 44, 4, 36, 14, 46, 6, 38],
  [60, 28, 52, 20, 62, 30, 54, 22], [3, 35, 11, 43, 1, 33, 9, 41], [51, 19, 59, 27, 49, 17, 57, 25],
  [15, 47, 7, 39, 13, 45, 5, 37], [63, 31, 55, 23, 61, 29, 53, 21]];
const dither = (x, y) => (BAYER[y & 7][x & 7] + 0.5) / 64;

export function createPixel() {
  const native = document.createElement('canvas');
  native.width = W; native.height = H;
  const ctx = native.getContext('2d');
  const plot = (x, y, color) => {
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    ctx.fillStyle = color; ctx.fillRect(x, y, 1, 1);
  };
  const box = (x, y, w, h, color) => { for (let j = y; j < y + h; j++) for (let i = x; i < x + w; i++) plot(i, j, color); };
  const poly = (pts, color) => {
    const ys = pts.map(p => p[1]);
    for (let y = Math.floor(Math.min(...ys)); y <= Math.ceil(Math.max(...ys)); y++) {
      const xs = [];
      pts.forEach(([ax, ay], i) => {
        const [bx, by] = pts[(i + 1) % pts.length];
        if ((ay <= y + 0.5) !== (by <= y + 0.5)) xs.push(ax + (y + 0.5 - ay) * (bx - ax) / (by - ay));
      });
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) for (let x = Math.round(xs[k]); x < Math.round(xs[k + 1]); x++) plot(x, y, typeof color === 'function' ? color(x, y) : color);
    }
  };
  const line = (a, b, color) => {
    let [x, y] = a; const [tx, ty] = b;
    const dx = Math.abs(tx - x), dy = -Math.abs(ty - y), sx = x < tx ? 1 : -1, sy = y < ty ? 1 : -1;
    let err = dx + dy;
    while (true) {
      plot(x, y, color);
      if (x === tx && y === ty) break;
      const e = 2 * err;
      if (e >= dy) { err += dy; x += sx; }
      if (e <= dx) { err += dx; y += sy; }
    }
  };

  const canvas = document.createElement('canvas');
  canvas.width = W * U; canvas.height = H * U; document.body.append(canvas);
  const out = canvas.getContext('2d');
  out.imageSmoothingEnabled = false;

  function render(s) {
    for (let y = 0; y < 147; y++) for (let x = 0; x < W; x++) {
      const t = Math.pow(y / 118, 1.15) * (C.sky.length - 1);
      const base = Math.min(C.sky.length - 1, Math.floor(t));
      const pick = t - base > dither(x, y) ? Math.min(C.sky.length - 1, base + 1) : base;
      plot(x, y, C.sky[pick]);
    }
    for (let y = SUN.y - SUN.r; y <= SUN.y + SUN.r; y++) for (let x = SUN.x - SUN.r; x <= SUN.x + SUN.r; x++) {
      if (Math.hypot(x - SUN.x, y - SUN.y) <= SUN.r) plot(x, y, C.sun);
    }
    for (const [x, y, size] of STARS.slice(0, s.stars)) {
      plot(x, y, C.lamp);
      if (size >= 1) { plot(x - 1, y, C.lamp); plot(x + 1, y, C.lamp); plot(x, y - 1, C.lamp); plot(x, y + 1, C.lamp); }
      if (size >= 2) { plot(x, y, C.sun); plot(x - 2, y, C.lamp); plot(x + 2, y, C.lamp); plot(x, y - 2, C.lamp); plot(x, y + 2, C.lamp); }
    }

    poly(skylinePolygon(SKYLINE.far), C.far);
    poly(skylinePolygon(SKYLINE.mid), C.mid);
    SKYLINE.mid.lights.forEach((l, i) => { if (isLit(i, s.lit)) plot(l.x, l.y, l.warm ? C.sun : C.far); });

    const bandColor = y => TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] || 'red';
    for (let y = TOWER.top; y < TOWER.base; y++) {
      const half = towerHalf(y), arch = towerArch(y), key = bandColor(y);
      const hi = key === 'red' ? C.red : C.white, lo = key === 'red' ? C.redDark : C.whiteDark;
      const r = Math.round(half);
      for (let dx = -r; dx <= r; dx++) {
        const x = TOWER.cx + dx, abs = Math.abs(dx);
        if (arch && abs < arch) continue;
        const deck = (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) || (y >= TOWER.topDeck[0] && y < TOWER.topDeck[1]);
        const edge = r - abs < 2, brace = (x + y) % 5 === 0 || (x - y + 500) % 5 === 0, girder = y % 6 === 0;
        if (deck || r <= 2 || edge || brace || girder) plot(x, y, dx > 0 && !deck ? lo : hi);
      }
    }
    for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
      for (let x = TOWER.cx - half + 1; x < TOWER.cx + half; x += 2) plot(x, a + 1, C.rail);
      box(TOWER.cx - half, b - 1, half * 2 + 1, 1, C.redDark);
    }

    poly(skylinePolygon(SKYLINE.near), (x, y) => (y > 138 && (x + y) % 2 === 0 ? C.nearDark : C.near));
    SKYLINE.near.lights.forEach((l, i) => {
      if (!isLit(i + 1000, s.lit)) return;
      plot(l.x, l.y, l.warm ? C.lamp : C.sun); plot(l.x + 1, l.y, l.warm ? C.lamp : C.sun);
    });
    box(0, RAIL.top, W, 1, C.rail); box(0, RAIL.low, W, 1, C.nearDark);
    for (const x of RAIL.posts) box(x, RAIL.top, 1, RAIL.wall - RAIL.top, C.rail);
    box(0, RAIL.wall, W, RAIL.floor - RAIL.wall, C.nearDark);
    box(0, RAIL.wall, W, 1, C.rail);

    for (let y = RAIL.floor; y < H; y++) for (let x = 0; x < W; x++) {
      const glow = 1 - Math.min(1, Math.abs(x - SUN.x) / 150) - (y - RAIL.floor) / 90;
      plot(x, y, glow * 0.8 > dither(x, y) ? C.floor : C.floorDark);
    }
    for (const y of [152, 160, 171]) box(0, y, W, 1, C.floorShadow);

    const dappled = (x, y) => ((x + y) % 2 === 0 ? C.floorShadow : C.floorDark);
    const dc = s.caseX - SUITCASE.body[0];
    poly(SHADOW, dappled);
    poly(CASE_SHADOW.map(([x, y]) => [x + dc, y]), dappled);
    if (s.action === 'walk') box(s.x + 8, s.y + 26, 18, 2, dappled(s.x, s.y));

    for (const [x, y, w, h] of BENCH.legs) box(x, y, w, h, C.branch);
    box(...BENCH.brace, C.woodDark);

    const c = SUITCASE;
    box(c.handle[0] + dc, c.handle[1], c.handle[2], 1, C.branch);
    box(c.handle[0] + dc, c.handle[1], 1, c.handle[3], C.branch);
    box(c.handle[0] + c.handle[2] - 1 + dc, c.handle[1], 1, c.handle[3], C.branch);
    box(c.body[0] + dc, c.body[1], c.body[2], c.body[3], C.caseBody);
    box(c.body[0] + c.body[2] - 3 + dc, c.body[1], 3, c.body[3], C.caseDark);
    box(c.body[0] + dc, c.body[1] + c.body[3] - 1, c.body[2], 1, C.branch);
    for (const [x, y, w, h] of c.straps) box(x + dc, y, w, h, C.whiteDark);

    box(BENCH.x, BENCH.top, BENCH.w, BENCH.h - 1, C.wood);
    box(BENCH.x, BENCH.top + BENCH.h - 1, BENCH.w, 1, C.woodDark);
    for (let x = BENCH.x + 6; x < BENCH.x + BENCH.w; x += 9) plot(x, BENCH.top + 2, C.woodDark);

    drawCharacter(ctx, {x: s.x, y: s.y, scale: 1, facing: 'left', expression: 'neutral', action: s.action, frame: s.frame});

    TICKETS.forEach((t, i) => {
      const xs = t.map(q => q[0]), top = Math.max(t[0][1], t[1][1]);
      box(Math.min(...xs), top, Math.max(...xs) - Math.min(...xs), 143 - top, C.white);
      const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
      box(stub, Math.ceil(Math.max(t[0][1], t[1][1])), 2, 4, C.red);
    });

    for (const pts of BRANCH) for (let i = 1; i < pts.length; i++) line(pts[i - 1], pts[i], C.branch);
    LEAVES.forEach(([x, y], i) => poly(leafShape(x, y, i % 2 ? 1 : -1), i % 3 === 0 ? C.leafDark : C.leaf));

    out.drawImage(native, 0, 0, canvas.width, canvas.height);
  }
  return {canvas, native, render};
}

import {isLit, jitter} from './clip.js';
import {W, H, U, rng, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH, CLAWD,
  clawdParts, TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const PX = W * U, PY = H * U;
const CORE = '#fbf5e6';
const scale = pts => pts.map(([x, y]) => [x * U, y * U]);
const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];

function makeCanvas(w = PX, h = PY) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return c;
}

export function createPaper() {
  const r = rng(5170);

  // 沿边重采样并加噪声：撕纸用多尺度起伏，剪纸只留微小手抖。
  function roughen(pts, step, amp) {
    const out = [];
    let slow = r() * 6, fast = r() * 6;
    pts.forEach(([x, y], i) => {
      const [nx, ny] = pts[(i + 1) % pts.length], len = Math.hypot(nx - x, ny - y) || 1, n = Math.max(1, Math.ceil(len / step));
      for (let j = 0; j < n; j++) {
        slow += 0.22 + r() * 0.1; fast += 0.9 + r() * 0.6;
        const d = (Math.sin(slow) * 0.6 + Math.sin(fast) * 0.3 + (r() - 0.5) * 0.5) * amp, t = j / n;
        out.push([x + (nx - x) * t - (ny - y) / len * d, y + (ny - y) * t + (nx - x) / len * d]);
      }
    });
    return out;
  }

  function makeTexture(paint, w = PX, h = PY) {
    const c = makeCanvas(w, h);
    paint(c.getContext('2d'), w, h);
    return c;
  }
  const fibre = makeTexture((t, w, h) => {
    t.fillStyle = '#fff'; t.fillRect(0, 0, w, h);
    for (let i = 0; i < 9000; i++) {
      const x = r() * w, y = r() * h, a = r() * 6.3, l = 3 + r() * 14;
      t.strokeStyle = r() < 0.72 ? `rgba(90,70,45,${0.05 + r() * 0.12})` : 'rgba(255,255,255,.5)';
      t.lineWidth = 0.4 + r() * 0.7;
      t.beginPath(); t.moveTo(x, y); t.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); t.stroke();
    }
  });
  const kraft = makeTexture((t, w, h) => {
    t.fillStyle = '#c4a176'; t.fillRect(0, 0, w, h);
    for (let i = 0; i < 30000; i++) {
      const x = r() * w, y = r() * h, l = 4 + r() * 13, a = (r() - 0.5) * 1.6;
      t.strokeStyle = r() < 0.55 ? `rgba(95,66,36,${0.06 + r() * 0.16})` : `rgba(240,215,175,${0.08 + r() * 0.18})`;
      t.lineWidth = 0.4 + r() * 0.8;
      t.beginPath(); t.moveTo(x, y); t.lineTo(x + Math.cos(a) * l, y + Math.sin(a) * l); t.stroke();
    }
  });
  // 旧报纸只有灰色假字条与半调方块，没有可读文字。
  const news = makeTexture((t, w, h) => {
    t.fillStyle = '#eadfc8'; t.fillRect(0, 0, w, h);
    const cols = 5, cw = w / cols;
    for (let c = 0; c < cols; c++) {
      const x = c * cw + 10;
      for (let y = 8; y < h; y += 9) {
        if (c === 1 && y > 180 && y < 320) continue;
        let px = x;
        const end = x + cw - 20;
        while (px < end) {
          const len = 3 + r() * 13;
          t.fillStyle = `rgba(62,56,48,${0.42 + r() * 0.3})`;
          t.fillRect(px, y, Math.min(len, end - px), 3);
          px += len + 2.5;
        }
      }
    }
    t.fillStyle = 'rgba(62,56,48,.55)';
    for (let y = 184; y < 316; y += 5) for (let x = cw + 12; x < 2 * cw - 12; x += 5) {
      t.beginPath(); t.arc(x, y, 0.8 + 1.5 * Math.abs(Math.sin(x / 26 + y / 40)), 0, 7); t.fill();
    }
  }, 900, 720);

  let ctx;
  const trace = pts => { ctx.beginPath(); pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); ctx.closePath(); };
  const overlay = (tex, mode = 'multiply') => {
    ctx.globalCompositeOperation = mode;
    ctx.fillStyle = ctx.createPattern(tex, 'repeat');
    ctx.fillRect(0, 0, PX, PY);
    ctx.globalCompositeOperation = 'source-over';
  };

  function piece(points, {color, edge = 'cut', border = 7, lift = 1, tex = null, detail = null}) {
    const base = scale(points);
    const outer = edge === 'torn' ? roughen(base, 7, 7) : roughen(base, 34, 0.9);
    const inner = edge === 'torn' ? roughen(base, 7, 3.5) : outer;
    ctx.save();
    ctx.shadowColor = 'rgba(58,42,24,.42)'; ctx.shadowBlur = 7 + lift * 7; ctx.shadowOffsetX = 2 + lift * 2; ctx.shadowOffsetY = 3 + lift * 4;
    trace(outer);
    ctx.fillStyle = CORE; ctx.fill();
    if (edge === 'cut' && border) { ctx.strokeStyle = CORE; ctx.lineWidth = border; ctx.lineJoin = 'round'; ctx.stroke(); }
    ctx.restore();
    ctx.save();
    trace(inner); ctx.clip();
    if (tex) { ctx.fillStyle = ctx.createPattern(tex, 'repeat'); ctx.fillRect(0, 0, PX, PY); }
    if (color) {
      ctx.globalCompositeOperation = tex ? 'multiply' : 'source-over';
      ctx.fillStyle = color; ctx.fillRect(0, 0, PX, PY);
      ctx.globalCompositeOperation = 'source-over';
    }
    overlay(fibre);
    detail?.();
    ctx.restore();
  }
  const stripe = (pts, color, width, border = 4) => {
    const line = scale(pts);
    ctx.save();
    ctx.lineJoin = 'round'; ctx.lineCap = 'round';
    ctx.shadowColor = 'rgba(58,42,24,.4)'; ctx.shadowBlur = 7; ctx.shadowOffsetX = 2; ctx.shadowOffsetY = 4;
    const path = () => { ctx.beginPath(); line.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); };
    path(); ctx.strokeStyle = CORE; ctx.lineWidth = width + border; ctx.stroke();
    ctx.shadowColor = 'transparent';
    path(); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
    ctx.restore();
  };

  // 每层画在独立透明画布上，动画时整层一起抖动。
  let layerCount = 0;
  const layer = paint => {
    const canvas = makeCanvas();
    ctx = canvas.getContext('2d');
    paint();
    return {canvas, id: layerCount++};
  };

  const base = makeCanvas();
  {
    const b = base.getContext('2d');
    b.fillStyle = b.createPattern(kraft, 'repeat'); b.fillRect(0, 0, PX, PY);
  }
  const sky = layer(() => {
    piece([[3, 62], [317, 58], [316, 148], [4, 148]], {color: '#f3c99c', edge: 'torn', lift: 0.6});
    piece([[4, 30], [316, 27], [317, 72], [210, 80], [110, 72], [4, 78]], {color: '#f2e6c8', edge: 'torn', lift: 0.8});
    piece([[3, 3], [317, 4], [316, 34], [230, 41], [120, 33], [3, 42]], {color: '#b4c9ca', edge: 'torn', lift: 1});
  });
  const sun = layer(() => piece(Array.from({length: 40}, (_, i) => [SUN.x + Math.cos(i / 40 * 6.283) * SUN.r, SUN.y + Math.sin(i / 40 * 6.283) * SUN.r]), {color: '#f9dd8e', lift: 0.7}));
  const stars = STARS.map(([x, y, size]) => layer(() => {
    const a = 1.6 + size * 1.5, b = a * 0.3;
    piece([[x, y - a], [x + b, y - b], [x + a, y], [x + b, y + b], [x, y + a], [x - b, y + b], [x - a, y], [x - b, y - b]], {color: C.lamp, border: 4, lift: 0.3});
  }));
  const far = layer(() => piece(skylinePolygon(SKYLINE.far), {tex: news, color: '#efe2c9', edge: 'torn', lift: 0.8}));
  const building = (b, color, buildingLift, bottom = 147) => {
    const tilt = (r() - 0.5) * 0.9;
    piece([[b.x, b.top + tilt], [b.x + b.w, b.top - tilt], [b.x + b.w + tilt, bottom], [b.x, bottom]], {color, border: 3.5, lift: buildingLift});
  };
  const mid = layer(() => SKYLINE.mid.buildings.forEach((b, i) => building(b, i % 2 ? C.mid : '#a9b6b0', 0.5)));

  const tower = layer(() => {
    const left = [], right = [];
    for (let y = TOWER.top; y <= TOWER.base; y++) { left.push([TOWER.cx - towerHalf(y), y]); right.unshift([TOWER.cx + towerHalf(y), y]); }
    const archPts = [];
    for (let y = TOWER.base; y >= 117; y--) archPts.push([TOWER.cx - towerArch(y), y]);
    for (let y = 117; y <= TOWER.base; y++) archPts.push([TOWER.cx + towerArch(y), y]);
    piece([...left, ...archPts, ...right], {color: C.white, border: 6, lift: 1.2, detail: () => {
      for (const [a, b, key] of TOWER.bands) {
        if (key !== 'red') continue;
        ctx.fillStyle = C.red; ctx.fillRect(0, a * U, PX, (b - a) * U);
      }
      ctx.lineCap = 'round';
      for (let y = 58; y < TOWER.base; y += 6) {
        if (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) continue;
        const h1 = towerHalf(y), h2 = towerHalf(y + 6);
        ctx.strokeStyle = TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] === 'red' ? C.redDark : '#b9ac94';
        ctx.lineWidth = 3;
        const seg = (x1, y1, x2, y2) => { ctx.beginPath(); ctx.moveTo(x1 * U, y1 * U); ctx.lineTo(x2 * U, y2 * U); ctx.stroke(); };
        seg(TOWER.cx - h1, y, TOWER.cx + h2, y + 6); seg(TOWER.cx + h1, y, TOWER.cx - h2, y + 6);
        seg(TOWER.cx - h1, y, TOWER.cx + h1, y);
      }
    }});
    for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
      piece(rect(TOWER.cx - half, a, half * 2, b - a), {color: C.white, border: 4, lift: 0.7, detail: () => {
        ctx.fillStyle = C.rail;
        for (let x = TOWER.cx - half + 1; x < TOWER.cx + half - 0.5; x += 2) ctx.fillRect(x * U, (a + 1) * U, 5, 8);
        ctx.fillStyle = C.redDark; ctx.fillRect(0, (b - 1) * U, PX, U);
      }});
    }
  });
  const near = layer(() => SKYLINE.near.buildings.forEach((b, i) => building(b, i % 3 === 0 ? C.nearDark : C.near, 0.7)));
  const rail = layer(() => {
    stripe([[-2, RAIL.low], [W + 2, RAIL.low]], C.nearDark, 5, 3);
    for (const x of RAIL.posts) stripe([[x, RAIL.top], [x, RAIL.wall]], C.rail, 6, 3);
    stripe([[-2, RAIL.top], [W + 2, RAIL.top]], C.rail, 8, 3);
    piece([[-3, RAIL.wall], [W + 3, RAIL.wall], [W + 3, RAIL.floor + 3], [-3, RAIL.floor + 3]], {color: C.nearDark, edge: 'torn', lift: 0.9});
  });
  const floor = layer(() => {
    piece([[-4, RAIL.floor], [W + 4, RAIL.floor], [W + 4, H + 4], [-4, H + 4]], {tex: kraft, color: '#efe0c4', edge: 'torn', lift: 1.2, detail: () => {
      ctx.strokeStyle = 'rgba(90,66,40,.2)'; ctx.lineWidth = 3;
      for (const y of [152, 160, 171]) { ctx.beginPath(); ctx.moveTo(0, y * U); ctx.lineTo(PX, y * U + (r() - 0.5) * 8); ctx.stroke(); }
    }});
    trace(roughen(scale(SHADOW), 14, 2)); ctx.fillStyle = 'rgba(84,62,42,.3)'; ctx.fill();
  });
  const benchLegs = layer(() => {
    for (const [x, y, w, h] of BENCH.legs) piece(rect(x, y, w, h), {color: C.branch, border: 5, lift: 0.8});
    piece(rect(...BENCH.brace), {color: C.woodDark, border: 4, lift: 0.5});
  });
  const suitcase = layer(() => {
    const c = SUITCASE;
    trace(roughen(scale(CASE_SHADOW), 14, 2)); ctx.fillStyle = 'rgba(84,62,42,.3)'; ctx.fill();
    stripe([[c.handle[0], c.body[1]], [c.handle[0], c.handle[1]], [c.handle[0] + c.handle[2], c.handle[1]], [c.handle[0] + c.handle[2], c.body[1]]], C.branch, 6, 3);
    piece(rect(...c.body), {color: C.caseBody, lift: 1.1, detail: () => {
      ctx.fillStyle = C.caseDark; ctx.fillRect((c.body[0] + c.body[2] - 3) * U, 0, 3 * U, PY);
    }});
    for (const s of c.straps) piece(rect(...s), {color: C.whiteDark, border: 2, lift: 0.2});
  });
  const plank = layer(() => {
    piece(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), {color: C.wood, lift: 1.2, detail: () => {
      for (let i = 0; i < 26; i++) {
        const y = (BENCH.top + r() * BENCH.h) * U, x = (BENCH.x + r() * BENCH.w * 0.8) * U;
        ctx.strokeStyle = 'rgba(92,62,38,.4)'; ctx.lineWidth = 1 + r() * 1.5;
        ctx.beginPath(); ctx.moveTo(x, y); ctx.bezierCurveTo(x + 40, y + 2, x + 80, y - 2, x + 90 + r() * 70, y + 1); ctx.stroke();
      }
    }});
  });

  const clawdId = layerCount++;
  const poses = new Map();
  const pose = (action, frame) => {
    const key = `${action}:${frame}`;
    if (!poses.has(key)) {
      const canvas = makeCanvas();
      ctx = canvas.getContext('2d');
      const p = clawdParts(CLAWD.x, CLAWD.y, action, frame);
      if (action === 'walk') {
        ctx.fillStyle = 'rgba(84,62,42,.3)';
        ctx.beginPath(); ctx.ellipse((CLAWD.x + 16) * U, (CLAWD.y + 27) * U, 9 * U, 1.6 * U, 0, 0, 7); ctx.fill();
      }
      piece(rect(...p.armBack), {color: '#b85d47', border: 5, lift: 0.5});
      for (const leg of p.legs) piece(rect(...leg), {color: '#b85d47', border: 4, lift: 0.5});
      piece(rect(...p.body), {color: '#da7758', lift: 1.5, detail: () => {
        ctx.fillStyle = '#b85d47'; ctx.fillRect(p.body[0] * U, 0, 2.2 * U, PY);
        ctx.fillStyle = '#ed9b75'; ctx.fillRect(p.body[0] * U, p.body[1] * U, p.body[2] * U, 1.3 * U);
      }});
      piece(rect(...p.arm), {color: '#ed9b75', border: 5, lift: 0.8});
      piece(rect(...p.eye), {color: '#352e2a', border: 3, lift: 0.2});
      poses.set(key, canvas);
    }
    return poses.get(key);
  };
  const tickets = layer(() => TICKETS.forEach((t, i) => piece(t, {color: C.white, border: 4, lift: 0.8, detail: () => {
    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
    ctx.fillStyle = C.red; ctx.fillRect(stub * U, 0, 2 * U, PY);
  }})));
  const branch = layer(() => {
    for (const pts of BRANCH) stripe(pts, C.branch, 7, 4);
    LEAVES.forEach(([x, y], i) => {
      const s = leafShape(x, y, i % 2 ? 1 : -1).map(([a, b]) => [x + (a - x) * 1.25, y + (b - y) * 1.25]);
      piece(s, {color: i % 3 === 0 ? C.leafDark : C.leaf, border: 3, lift: 0.6});
    });
  });

  const canvas = makeCanvas();
  document.body.append(canvas);
  const out = canvas.getContext('2d');

  function render(s, tick = null) {
    const shake = id => (tick === null ? {dx: 0, dy: 0} : jitter(id, tick));
    const put = (l, ox = 0, oy = 0) => {
      const {dx, dy} = shake(l.id);
      out.drawImage(l.canvas, ox + dx, oy + dy);
    };
    const lights = (list, offset, l, width, color) => {
      const {dx, dy} = shake(l.id);
      out.save();
      out.shadowColor = 'rgba(40,40,30,.35)'; out.shadowBlur = 2; out.shadowOffsetY = 1;
      list.forEach((light, i) => {
        if (!isLit(i + offset, s.lit)) return;
        out.fillStyle = color(light);
        out.fillRect(light.x * U + dx, light.y * U + dy, width, 8);
      });
      out.restore();
    };
    out.drawImage(base, 0, 0);
    put(sky); put(sun);
    stars.slice(0, s.stars).forEach(l => put(l));
    put(far); put(mid);
    lights(SKYLINE.mid.lights, 0, mid, 7, l => (l.warm ? C.sun : CORE));
    put(tower); put(near);
    lights(SKYLINE.near.lights, 1000, near, 10, l => (l.warm ? C.lamp : C.sun));
    put(rail); put(floor); put(benchLegs);
    put(suitcase, (s.caseX - SUITCASE.body[0]) * U);
    put(plank);
    put({canvas: pose(s.action, s.frame), id: clawdId}, (s.x - CLAWD.x) * U, (s.y - CLAWD.y) * U);
    put(tickets); put(branch);
  }
  return {canvas, render};
}

/* global p5, brush */
import {isLit} from './clip.js';
import {W, H, U, rng, COLORS as C, TOWER, towerHalf, towerArch, SKYLINE, skylinePolygon, SUN, STARS, RAIL, BENCH, CLAWD,
  clawdParts, TICKETS, SUITCASE, SHADOW, CASE_SHADOW, BRANCH, LEAVES, leafShape} from './scene.js';

const PX = W * U, PY = H * U;
const PAPER = '#f6efdf';
let r = rng(7741);
const rect = (x, y, w, h) => [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];

// 把多边形扫描成一组平行线段，线段就是一笔一笔的蜡笔排线。
function hatchSpans(points, angle, gap) {
  const a = angle * Math.PI / 180, cos = Math.cos(a), sin = Math.sin(a);
  const rot = points.map(([x, y]) => [x * cos + y * sin, -x * sin + y * cos]);
  const vs = rot.map(p => p[1]), spans = [];
  for (let v = Math.min(...vs) + gap * 0.4; v < Math.max(...vs); v += gap * (0.8 + r() * 0.4)) {
    const hits = [];
    rot.forEach(([x0, y0], i) => {
      const [x1, y1] = rot[(i + 1) % rot.length];
      if ((y0 <= v) !== (y1 <= v)) hits.push(x0 + (v - y0) * (x1 - x0) / (y1 - y0));
    });
    hits.sort((p, q) => p - q);
    for (let k = 0; k + 1 < hits.length; k += 2) {
      spans.push([[hits[k], v], [hits[k + 1], v]].map(([u, w]) => [u * cos - w * sin, u * sin + w * cos]));
    }
  }
  return spans;
}

// 蜡笔不能盖住底色，所以先给后画的物体留出纸白：reserved(x, y) 为真的位置不下笔。
function splitAround(span, reserved) {
  const [[x0, y0], [x1, y1]] = span, len = Math.hypot(x1 - x0, y1 - y0), n = Math.ceil(len / 8), out = [];
  let start = null;
  for (let i = 0; i <= n; i++) {
    const t = i / n, x = x0 + (x1 - x0) * t, y = y0 + (y1 - y0) * t, free = !reserved(x / U, y / U);
    if (free && !start) start = [x, y];
    if (start && (!free || i === n)) { out.push([start, [x, y]]); start = null; }
  }
  return out;
}

function scribble(points, color, {angle = 20, gap = 9, weight = 1, over = 3, alpha = 1, wob = 3, reserved = null, passes = 2} = {}) {
  for (let pass = 1; pass < passes; pass++) scribble(points, color, {angle: angle + 7 * pass, gap, weight, over, alpha, wob, reserved, passes: 1});
  const px = points.map(([x, y]) => [x * U, y * U]);
  brush.set('wax', color, weight);
  let spans = hatchSpans(px, angle + (r() - 0.5) * 3, gap);
  if (reserved) spans = spans.flatMap(s => splitAround(s, reserved));
  for (const [[x0, y0], [x1, y1]] of spans) {
    const len = Math.hypot(x1 - x0, y1 - y0);
    if (len < 2) continue;
    const ox = (x1 - x0) / len * (r() - 0.3) * over, oy = (y1 - y0) / len * (r() - 0.3) * over;
    const mx = (x0 + x1) / 2 + (r() - 0.5) * wob, my = (y0 + y1) / 2 + (r() - 0.5) * wob;
    if (len < 40) brush.line(x0 - ox, y0 - oy, x1 + ox, y1 + oy);
    else brush.spline([[x0 - ox, y0 - oy, 0.75 * alpha], [mx, my, alpha], [x1 + ox, y1 + oy, 0.8 * alpha]], 0.5);
  }
}

function outline(points, color, weight = 0.5, closed = true) {
  brush.set('wax', color, weight);
  const pts = closed ? [...points, points[0]] : points;
  for (let i = 1; i < pts.length; i++) {
    const j = 1.6;
    brush.line(pts[i - 1][0] * U + (r() - 0.5) * j, pts[i - 1][1] * U + (r() - 0.5) * j, pts[i][0] * U + (r() - 0.5) * j, pts[i][1] * U + (r() - 0.5) * j);
  }
}

const inTower = (x, y) => y >= TOWER.top - 1 && y <= TOWER.base && Math.abs(x - TOWER.cx) <= towerHalf(y) + 1.2 && Math.abs(x - TOWER.cx) >= towerArch(y) - 0.5;
const inSun = (x, y) => Math.hypot(x - SUN.x, y - SUN.y) <= SUN.r + 0.5;
const inBox = (x, y, [bx, by, bw, bh], m = 1) => x >= bx - m && x <= bx + bw + m && y >= by - m && y <= by + bh + m;
const inFront = (x, y) => inBox(x, y, [BENCH.x, BENCH.top, BENCH.w, BENCH.h]) || inBox(x, y, [177, 137, 25, 6]);
const inBench = (x, y) => inBox(x, y, [BENCH.x, BENCH.top, BENCH.w, BENCH.h]) || BENCH.legs.some(l => inBox(x, y, l)) || inBox(x, y, BENCH.brace);

// 一笔一笔地铺大面积，长度、角度、粗细都随机，避免规则条纹。
function freehand(top, bottom, count, colorAt, reserved) {
  for (let i = 0; i < count; i++) {
    const x = r() * (PX + 300) - 150, y = (top + r() * (bottom - top)) * U;
    const len = 150 + r() * 420, a = (-6 + r() * 7) * Math.PI / 180;
    const span = [[x, y], [x + Math.cos(a) * len, y + Math.sin(a) * len]];
    brush.set('wax', colorAt(y / U), 2.4 + r() * 2.2);
    for (const [[x0, y0], [x1, y1]] of splitAround(span, reserved)) {
      if (Math.hypot(x1 - x0, y1 - y0) < 8) continue;
      brush.spline([[x0, y0, 0.7], [(x0 + x1) / 2 + (r() - 0.5) * 8, (y0 + y1) / 2 + (r() - 0.5) * 10, 1], [x1, y1, 0.75]], 0.5);
    }
  }
}

function paintBackground() {
  const SKY = ['#c9dcdd', '#deeae0', '#f8f2d8', '#fef4d2', '#fee5bf', '#fbd0a6'];
  freehand(0, 147, 1250, y => SKY[Math.round(Math.min(1, Math.max(0, y / 122 + (r() - 0.5) * 0.14)) * (SKY.length - 1))],
    (x, y) => inTower(x, y) || inSun(x, y));

  const sun = Array.from({length: 28}, (_, i) => [SUN.x + Math.cos(i / 28 * 6.283) * SUN.r, SUN.y + Math.sin(i / 28 * 6.283) * SUN.r]);
  scribble(sun, '#f9dc82', {angle: 30, gap: 4.5, weight: 1.6, over: 1});
  scribble(sun, C.sun, {angle: -40, gap: 8, weight: 1.2, over: 1});

  scribble(skylinePolygon(SKYLINE.far), '#e0d3b8', {angle: 88, gap: 6, weight: 1.6, over: 2, reserved: inTower});
  scribble(skylinePolygon(SKYLINE.mid), '#c1cdc5', {angle: 80, gap: 5, weight: 1.7, over: 2, reserved: inTower});
  scribble(skylinePolygon(SKYLINE.mid), '#a9b9b3', {angle: 62, gap: 18, weight: 1.1, over: 2, reserved: inTower});
  outline(skylinePolygon(SKYLINE.mid).slice(1, -1), '#90a29f', 0.8, false);

  // 铁塔分色涂满再压桁架。
  for (const [a, b, key] of TOWER.bands) {
    const rows = [];
    for (let y = a; y <= b; y++) rows.push(y);
    if (a >= 117) {
      const lo = rows.map(y => [TOWER.cx - towerHalf(y), y]), inL = rows.slice().reverse().map(y => [TOWER.cx - Math.max(towerArch(y), 0.1), y]);
      const inR = rows.map(y => [TOWER.cx + Math.max(towerArch(y), 0.1), y]), ro = rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y]);
      for (const leg of [[...lo, ...inL], [...inR, ...ro]]) {
        scribble(leg, '#e26f4d', {angle: 70, gap: 2.6, weight: 1.1, over: 1, wob: 1});
      }
      continue;
    }
    const band = [...rows.map(y => [TOWER.cx - towerHalf(y), y]), ...rows.slice().reverse().map(y => [TOWER.cx + towerHalf(y), y])];
    scribble(band, key === 'red' ? '#e26f4d' : C.white, {angle: 72, gap: key === 'red' ? 2.6 : 5, weight: 1, over: 1, wob: 1});
    if (key === 'white') scribble(band, '#c9b99d', {angle: -50, gap: 11, weight: 0.8, over: 1, wob: 1});
  }
  for (let y = 58; y < TOWER.base - 6; y += 6) {
    if (y >= TOWER.mainDeck[0] && y < TOWER.mainDeck[1]) continue;
    const h1 = towerHalf(y), h2 = towerHalf(y + 6), red = TOWER.bands.find(([a, b]) => y >= a && y < b)?.[2] === 'red';
    brush.set('wax', red ? '#7f2d1f' : '#8f8169', 0.9);
    brush.line((TOWER.cx - h1) * U, y * U, (TOWER.cx + h2) * U, (y + 6) * U);
    brush.line((TOWER.cx + h1) * U, y * U, (TOWER.cx - h2) * U, (y + 6) * U);
  }
  const edgeL = [], edgeR = [];
  for (let y = TOWER.top; y <= 128; y += 2) { edgeL.push([TOWER.cx - towerHalf(y), y]); edgeR.push([TOWER.cx + towerHalf(y), y]); }
  outline(edgeL, '#7f2d1f', 1.6, false);
  outline(edgeR, '#7f2d1f', 1.6, false);
  for (const [a, b, half] of [TOWER.mainDeck, TOWER.topDeck]) {
    outline(rect(TOWER.cx - half, a, half * 2, b - a), '#6d4a3c', 1.6);
    brush.set('wax', C.rail, 1);
    for (let x = TOWER.cx - half + 1; x < TOWER.cx + half - 0.5; x += 2) brush.line(x * U, (a + 1) * U, x * U + 3, (a + 2) * U);
  }

  scribble(skylinePolygon(SKYLINE.near), '#a4b7ba', {angle: 76, gap: 4, weight: 2, over: 2, reserved: inFront});
  scribble(skylinePolygon(SKYLINE.near), '#8ca2a8', {angle: 52, gap: 12, weight: 1.4, over: 2, reserved: inFront});
  outline(skylinePolygon(SKYLINE.near).slice(1, -1), C.rail, 1.1, false);

  brush.set('wax', C.rail, 1.9);
  brush.spline([[-20, RAIL.top * U + 2], [PX / 2, RAIL.top * U - 3], [PX + 20, RAIL.top * U + 2]], 0.3);
  brush.set('wax', C.nearDark, 1.3);
  brush.spline([[-20, RAIL.low * U], [PX / 2, RAIL.low * U + 3], [PX + 20, RAIL.low * U - 1]], 0.3);
  for (const x of RAIL.posts) {
    brush.set('wax', C.rail, 1.5);
    brush.line(x * U, RAIL.top * U, x * U + (r() - 0.5) * 3, RAIL.wall * U);
  }
  scribble(rect(-4, RAIL.wall, W + 8, RAIL.floor - RAIL.wall), '#88a0a6', {angle: 8, gap: 4, weight: 1.5, over: 6, reserved: inFront});

  freehand(RAIL.floor + 1, H + 2, 520, () => (r() < 0.72 ? '#ecdab2' : '#dcc698'), (x, y) => y < RAIL.floor || inBench(x, y));
  scribble(SHADOW, '#b5a58a', {angle: 32, gap: 5, weight: 1.7, over: 2});

  for (const leg of BENCH.legs) {
    scribble(rect(...leg), C.branch, {angle: 84, gap: 2.2, weight: 1.1, over: 1, wob: 1});
  }
  scribble(rect(...BENCH.brace), C.woodDark, {angle: 2, gap: 2.5, weight: 1, over: 2, wob: 1});

  scribble(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), '#cda172', {angle: 3, gap: 3, weight: 1.5, over: 5, wob: 2});
  scribble(rect(BENCH.x, BENCH.top + 3, BENCH.w, 2), '#a87d57', {angle: 1, gap: 2.5, weight: 1, over: 3, wob: 1});
  outline(rect(BENCH.x, BENCH.top, BENCH.w, BENCH.h), '#5c3f2e', 1.6);

  TICKETS.forEach((t, i) => {
    scribble(t, C.white, {angle: 10, gap: 2.4, weight: 1, over: 1, wob: 1});
    const stub = i === 0 ? t[0][0] + 2 : t[1][0] - 3;
    scribble(rect(stub, Math.max(t[0][1], t[1][1]) + 0.3, 2, 4), C.red, {angle: 85, gap: 2, weight: 1, over: 0.5, wob: 1});
    outline(t, '#6d4a3c', 1.3);
  });

  for (const pts of BRANCH) outline(pts, C.branch, 2.2, false);
  LEAVES.forEach(([x, y], i) => {
    const s = leafShape(x, y, i % 2 ? 1 : -1).map(([a, b]) => [x + (a - x) * 1.25, y + (b - y) * 1.25]);
    scribble(s, i % 3 === 0 ? '#dcaa41' : '#efc962', {angle: 40 + i * 13, gap: 2.2, weight: 1.1, over: 1, wob: 1});
  });
}

// 灯和光点集中画在白底上，逐帧按区域取用。
const crayonLights = [
  ...SKYLINE.mid.lights.map((l, i) => ({...l, order: i, w: 6, h: 4})),
  ...SKYLINE.near.lights.map((l, i) => ({...l, order: i + 1000, w: 10, h: 7})),
].filter(l => l.y < RAIL.wall - 1 && !inFront(l.x, l.y));

function paintEffects() {
  for (const [x, y, size] of STARS) {
    const a = (1.5 + size * 1.4) * U;
    brush.set('wax', '#dd9226', 0.9 + size * 0.3);
    brush.line(x * U - a, y * U, x * U + a, y * U);
    brush.line(x * U, y * U - a, x * U, y * U + a);
  }
  for (const l of crayonLights) {
    brush.set('wax', l.w > 6 ? '#f1b73f' : '#f3cf74', l.w > 6 ? 1.2 : 0.8);
    brush.line(l.x * U, l.y * U, l.x * U + l.w - 1, l.y * U + 1);
    if (l.w > 6) brush.line(l.x * U + 1, l.y * U + 4, l.x * U + 8, l.y * U + 4);
  }
}

function paintSuitcase() {
  const c = SUITCASE;
  scribble(CASE_SHADOW, '#b5a58a', {angle: 32, gap: 5, weight: 1.7, over: 2});
  outline([[c.handle[0], c.body[1]], [c.handle[0], c.handle[1]], [c.handle[0] + c.handle[2], c.handle[1]], [c.handle[0] + c.handle[2], c.body[1]]], C.branch, 1.6, false);
  scribble(rect(...c.body), '#8fafa5', {angle: 75, gap: 3, weight: 1.6, over: 1, wob: 2});
  scribble(rect(c.body[0] + c.body[2] - 4, c.body[1], 4, c.body[3]), '#6f9087', {angle: 70, gap: 2.8, weight: 1.1, over: 1, wob: 1});
  for (const s of c.straps) { brush.set('wax', C.white, 0.9); brush.line(s[0] * U + 3, s[1] * U, s[0] * U + 3, (s[1] + s[3]) * U); }
  outline(rect(...c.body), '#3f5650', 1.5);
}

function paintClawd(p, walking) {
  if (walking) {
    scribble(rect(CLAWD.x + 7, CLAWD.y + 26, 18, 2), '#b5a58a', {angle: 4, gap: 3, weight: 1.2, over: 1, wob: 1});
  }
  for (const leg of p.legs) scribble(rect(...leg), '#a84f3c', {angle: 88, gap: 2.2, weight: 1, over: 1, wob: 1});
  scribble(rect(...p.armBack), '#a84f3c', {angle: 10, gap: 2.4, weight: 1, over: 1, wob: 1});
  scribble(rect(...p.body), '#e58a68', {angle: 58, gap: 2.8, weight: 1.8, over: 1, wob: 2});
  scribble(rect(...p.body), '#d97c5a', {angle: -38, gap: 7, weight: 1.2, over: 1, wob: 2});
  scribble(rect(p.body[0], p.body[1] + 2, 3, p.body[3] - 2), '#a84f3c', {angle: 80, gap: 2.4, weight: 1, over: 1, wob: 1});
  scribble(rect(p.body[0] + 2, p.body[1], p.body[2] - 3, 1.5), '#f0a57f', {angle: 2, gap: 2.4, weight: 1, over: 1, wob: 1});
  outline(rect(...p.body), '#713f32', 2);
  scribble(rect(...p.arm), '#ed9b75', {angle: 10, gap: 2.2, weight: 1, over: 1, wob: 1});
  outline(rect(...p.arm), '#713f32', 1.6);
  scribble(rect(...p.eye), '#352e2a', {angle: 85, gap: 1.6, weight: 0.9, over: 0.5, wob: 0.5});
}

const POSES = [['idle', 0], ['walk', 0], ['walk', 1], ['walk', 2], ['walk', 3], ['jump', 1], ['jump', 2], ['jump', 3]];
const BACKGROUND_VARIANTS = 3, SPRITE_VARIANTS = 2;

// 笔触抖动：背景各版本共用同一组笔画，只换颗粒和 1 像素偏移，避免整片天空闪烁。
export function createCrayon(done) {
  let job = null;
  const instance = new p5(p => {
    brush.instance(p);
    p.setup = () => {
      const cnv = p.createCanvas(PX, PY, p.WEBGL);
      p.pixelDensity(1); p.noiseSeed(7741); p.angleMode(p.DEGREES);
      // 以内置 crayon 为基础，加厚蜡层、收紧颗粒，让单笔能看清走向。
      brush.add('wax', {type: 'default', weight: 0.62, scatter: 1.15, sharpness: 0.75, grain: 1.5, opacity: 190, spacing: 0.06, pressure: [1.1, 0.9], rotate: 'natural', noise: true});
      p.noLoop();
      cnv.elt.style.display = 'none';
      instance.source = cnv.elt;
    };
    p.draw = () => {
      if (!job) return;
      const current = job;
      job = null;
      p.randomSeed(current.seed);
      r = rng(current.strokes);
      p.background(current.paper); p.translate(-PX / 2 + current.dx, -PY / 2 + current.dy);
      brush.noField(); brush.noFill(); brush.noHatch();
      current.paint();
      requestAnimationFrame(() => {
        const copy = document.createElement('canvas');
        copy.width = PX; copy.height = PY;
        copy.getContext('2d').drawImage(instance.source, 0, 0, PX, PY);
        current.resolve(copy);
      });
    };
  });
  const capture = (paint, {paper = '#ffffff', seed, strokes = seed, dx = 0, dy = 0}) => new Promise(resolve => {
    job = {paint, paper, seed, strokes, dx, dy, resolve};
    instance.redraw();
  });

  async function build() {
    while (!instance.source) await new Promise(ok => setTimeout(ok, 20));
    const backgrounds = [];
    for (let i = 0; i < BACKGROUND_VARIANTS; i++) {
      backgrounds.push(await capture(paintBackground, {paper: PAPER, seed: 7741 + i, strokes: 7741, dx: i === 1 ? 1 : 0, dy: i === 2 ? 1 : 0}));
    }
    const effects = await capture(paintEffects, {seed: 501});
    const suitcases = [], sprites = new Map();
    for (let v = 0; v < SPRITE_VARIANTS; v++) {
      suitcases.push(await capture(paintSuitcase, {seed: 601 + v}));
      for (const [action, frame] of POSES) {
        const p = clawdParts(CLAWD.x, CLAWD.y, action, frame);
        sprites.set(`${action}:${frame}:${v}`, {canvas: await capture(() => paintClawd(p, action === 'walk'), {seed: 701 + v * 31 + frame}), parts: p});
      }
    }

    const tex = document.createElement('canvas');
    tex.width = 512; tex.height = 512;
    const t = tex.getContext('2d'), im = t.createImageData(512, 512);
    const grain = rng(911);
    for (let i = 0; i < im.data.length; i += 4) {
      const light = grain() > 0.72, v = light ? 255 : 70;
      im.data[i] = im.data[i + 1] = im.data[i + 2] = v; im.data[i + 3] = grain() * (light ? 30 : 24);
    }
    t.putImageData(im, 0, 0);

    const canvas = document.createElement('canvas');
    canvas.width = PX; canvas.height = PY;
    document.body.append(canvas);
    const ctx = canvas.getContext('2d');
    const knock = (x, y, w, h, m = 4) => { ctx.fillStyle = PAPER; ctx.fillRect(x * U - m, y * U - m, w * U + m * 2, h * U + m * 2); };
    const pigment = source => { ctx.globalCompositeOperation = 'multiply'; source(); ctx.globalCompositeOperation = 'source-over'; };

    function render(s, tick = 0) {
      const boil = tick ?? 0, variant = boil % SPRITE_VARIANTS;
      ctx.drawImage(backgrounds[Math.floor(boil / 2) % BACKGROUND_VARIANTS], 0, 0);

      pigment(() => STARS.slice(0, s.stars).forEach(([x, y, size]) => {
        const a = (2 + size * 1.4) * U + 4;
        ctx.drawImage(effects, x * U - a, y * U - a, a * 2, a * 2, x * U - a, y * U - a, a * 2, a * 2);
      }));
      for (const l of crayonLights) {
        if (!isLit(l.order, s.lit)) continue;
        ctx.fillStyle = PAPER; ctx.fillRect(l.x * U - 1, l.y * U - 2, l.w + 3, l.h + 3);
        pigment(() => ctx.drawImage(effects, l.x * U - 3, l.y * U - 4, l.w + 7, l.h + 7, l.x * U - 3, l.y * U - 4, l.w + 7, l.h + 7));
      }

      const dc = s.caseX - SUITCASE.body[0];
      knock(SUITCASE.body[0] + dc, SUITCASE.body[1], SUITCASE.body[2], SUITCASE.body[3]);
      pigment(() => ctx.drawImage(suitcases[variant], dc * U, 0));

      const sprite = sprites.get(`${s.action}:${s.frame}:${variant}`);
      const ox = s.x - CLAWD.x, oy = s.y - CLAWD.y, parts = sprite.parts;
      for (const box of [parts.body, parts.arm, parts.armBack, ...parts.legs]) knock(box[0] + ox, box[1] + oy, box[2], box[3], 3);
      pigment(() => ctx.drawImage(sprite.canvas, ox * U, oy * U));

      ctx.fillStyle = ctx.createPattern(tex, 'repeat'); ctx.fillRect(0, 0, PX, PY);
    }
    return {canvas, render, brushes: brush.box()};
  }
  build().then(done);
}

import {spawn} from 'node:child_process';
import {createServer} from 'node:http';
import {readFile, mkdir, mkdtemp, rm} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export const here = path.dirname(fileURLToPath(import.meta.url));
export const root = path.resolve(here, '../../..');
const CHROME = process.env.CHROME || '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const MIME = {'.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript'};

export async function openChrome() {
  const server = createServer(async (req, res) => {
    try {
      const file = path.join(root, decodeURIComponent(new URL(req.url, 'http://x').pathname));
      if (!file.startsWith(root)) throw new Error('outside root');
      const body = await readFile(file);
      res.writeHead(200, {'content-type': MIME[path.extname(file)] || 'application/octet-stream'});
      res.end(body);
    } catch { res.writeHead(404); res.end(); }
  });
  await new Promise(ok => server.listen(0, '127.0.0.1', ok));
  const port = server.address().port;

  await mkdir(path.join(root, '.agent/work'), {recursive: true});
  const profile = await mkdtemp(path.join(root, '.agent/work/opening-chrome-'));
  const chrome = spawn(CHROME, ['--headless=new', '--remote-debugging-port=0', `--user-data-dir=${profile}`,
    '--window-size=1920,1080', '--force-device-scale-factor=1', '--use-angle=swiftshader', '--enable-unsafe-swiftshader',
    '--ignore-gpu-blocklist', '--no-first-run', 'about:blank'], {stdio: ['ignore', 'ignore', 'pipe']});
  const wsUrl = await new Promise((ok, fail) => {
    let log = '';
    chrome.stderr.on('data', d => { log += d; const m = log.match(/ws:\/\/\S+/); if (m) ok(m[0]); });
    chrome.once('exit', code => fail(new Error(`Chrome 退出 ${code}: ${log}`)));
  });

  const ws = new WebSocket(wsUrl);
  await new Promise((ok, fail) => { ws.onopen = ok; ws.onerror = fail; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = e => {
    const msg = JSON.parse(e.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  };
  const send = (method, params = {}, sessionId) => new Promise((ok, fail) => {
    const n = ++id;
    pending.set(n, msg => (msg.error ? fail(new Error(`${method}: ${msg.error.message}`)) : ok(msg.result)));
    ws.send(JSON.stringify({id: n, method, params, sessionId}));
  });

  const {targetId} = await send('Target.createTarget', {url: 'about:blank'});
  const {sessionId} = await send('Target.attachToTarget', {targetId, flatten: true});
  const page = (method, params) => send(method, params, sessionId);
  const evaluate = async expression => {
    const r = await page('Runtime.evaluate', {expression, awaitPromise: true, returnByValue: true});
    if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
    return r.result.value;
  };
  await page('Emulation.setDeviceMetricsOverride', {width: 1920, height: 1080, deviceScaleFactor: 1, mobile: false});

  async function openStyle(style) {
    await page('Page.navigate', {url: `http://127.0.0.1:${port}/${encodeURI(path.relative(root, here))}/index.html?style=${style}`});
    let state = {};
    for (let i = 0; i < 2400; i++) {
      await new Promise(ok => setTimeout(ok, 250));
      state = await evaluate('({ready: !!window.artReady, errors: window.renderErrors || []})').catch(() => ({ready: false, errors: []}));
      if (state.ready || state.errors.length) break;
    }
    if (!state.ready || state.errors.length) throw new Error(`${style} 未完成: ${JSON.stringify(state)}`);
  }

  async function close() {
    const exited = new Promise(ok => chrome.once('exit', ok));
    chrome.kill(); server.close(); ws.close();
    await exited;
    await rm(profile, {recursive: true, force: true});
  }
  return {evaluate, openStyle, close};
}

// 用本机 Chrome 无头渲染静态样图并自检。用法：node render.mjs [pixel paper crayon]
import {writeFile} from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {openChrome, here} from './chrome.mjs';

const FILES = {pixel: '01-像素遊戲', paper: '02-紙藝拼貼', crayon: '03-蠟筆手繪'};
const styles = process.argv.slice(2).length ? process.argv.slice(2) : Object.keys(FILES);
const chrome = await openChrome();

const results = [];
try {
  for (const style of styles) {
    const started = Date.now();
    await chrome.openStyle(style);
    const r = await chrome.evaluate(`(() => {
      const c = window.art.canvas, d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
      const colors = new Set(); let opaque = true, blocks = true;
      for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) {
        const i = (y * c.width + x) * 4;
        colors.add(d[i] * 65536 + d[i + 1] * 256 + d[i + 2]);
        if (d[i + 3] !== 255) opaque = false;
        const j = ((y - y % 6) * c.width + (x - x % 6)) * 4;
        if (d[i] !== d[j] || d[i + 1] !== d[j + 1] || d[i + 2] !== d[j + 2]) blocks = false;
      }
      return {width: c.width, height: c.height, colors: colors.size, opaque, blocks,
        native: window.art.native ? [window.art.native.width, window.art.native.height] : null,
        brushes: window.art.brushes || null};
    })()`);
    assert.equal(r.width, 1920); assert.equal(r.height, 1080); assert.equal(r.opaque, true);
    if (style === 'pixel') {
      assert.deepEqual(r.native, [320, 180]);
      assert.ok(r.colors >= 16 && r.colors <= 32, `像素版 ${r.colors} 色超出 16–32`);
      assert.equal(r.blocks, true);
    }
    if (style === 'crayon') assert.ok(r.brushes.includes('crayon'));
    const png = await chrome.evaluate(`window.art.canvas.toDataURL('image/png').split(',')[1]`);
    await writeFile(path.join(here, `${FILES[style]}.png`), Buffer.from(png, 'base64'));
    results.push({style, ...r, brushes: undefined, errors: [], seconds: Math.round((Date.now() - started) / 1000)});
    console.log(JSON.stringify(results.at(-1)));
  }
} finally {
  await chrome.close();
}
if (styles.length === Object.keys(FILES).length) await writeFile(path.join(here, '驗證結果.json'), JSON.stringify(results, null, 2) + '\n');

// 渲染 00:14–00:24 试片并混入原曲。用法：node render-clip.mjs [pixel paper crayon]
import {spawn} from 'node:child_process';
import {mkdir, stat, writeFile} from 'node:fs/promises';
import path from 'node:path';
import assert from 'node:assert/strict';
import {openChrome, here, root} from './chrome.mjs';
import {CLIP, CLIP_FPS, clipTicks} from './clip.js';

const FILES = {pixel: '01-像素遊戲', paper: '02-紙藝拼貼', crayon: '03-蠟筆手繪'};
const AUDIO = path.join(root, '會呼吸的痛/會呼吸的痛.m4a');
const FULL_SONG_SECONDS = 273.043;
const outDir = path.join(here, '試片');
await mkdir(outDir, {recursive: true});
const styles = process.argv.slice(2).length ? process.argv.slice(2) : Object.keys(FILES);
const chrome = await openChrome();

function startEncoder(fps, target) {
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(fps), '-i', '-',
    '-ss', String(CLIP.start), '-t', String(CLIP.end - CLIP.start), '-i', AUDIO,
    '-map', '0:v', '-map', '1:a', '-r', '24', '-c:v', 'libx264', '-crf', '16', '-preset', 'medium', '-pix_fmt', 'yuv420p',
    '-c:a', 'aac', '-b:a', '192k', '-movflags', '+faststart', target], {stdio: ['pipe', 'inherit', 'inherit']});
  const finished = new Promise((ok, fail) => ffmpeg.once('exit', code => (code === 0 ? ok() : fail(new Error(`ffmpeg 退出 ${code}`)))));
  return {ffmpeg, finished};
}

const CHECK_PIXEL = `(() => {
  const c = window.art.canvas, d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
  const colors = new Set(); let blocks = true;
  for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) {
    const i = (y * c.width + x) * 4, j = ((y - y % 6) * c.width + (x - x % 6)) * 4;
    colors.add(d[i] * 65536 + d[i + 1] * 256 + d[i + 2]);
    if (d[i] !== d[j] || d[i + 1] !== d[j + 1] || d[i + 2] !== d[j + 2]) blocks = false;
  }
  return {colors: colors.size, blocks};
})()`;

const results = [];
try {
  for (const style of styles) {
    const fps = CLIP_FPS[style], ticks = clipTicks(fps), target = path.join(outDir, `${FILES[style]}.mp4`);
    const buildStart = Date.now();
    await chrome.openStyle(style);
    const buildSeconds = (Date.now() - buildStart) / 1000;

    const {ffmpeg, finished} = startEncoder(fps, target);
    const frameStart = Date.now();
    let maxColors = 0;
    for (let i = 0; i < ticks.length; i++) {
      const png = await chrome.evaluate(`(() => {
        window.art.render(window.clipState(${ticks[i]}), ${i});
        return window.art.canvas.toDataURL('image/png').split(',')[1];
      })()`);
      if (style === 'pixel' && i % 10 === 0) {
        const check = await chrome.evaluate(CHECK_PIXEL);
        assert.ok(check.colors <= 32, `第 ${i} 帧 ${check.colors} 色`);
        assert.equal(check.blocks, true, `第 ${i} 帧色块不完整`);
        maxColors = Math.max(maxColors, check.colors);
      }
      if (!ffmpeg.stdin.write(Buffer.from(png, 'base64'))) await new Promise(ok => ffmpeg.stdin.once('drain', ok));
    }
    ffmpeg.stdin.end();
    await finished;

    const frameSeconds = (Date.now() - frameStart) / 1000, perFrame = frameSeconds / ticks.length;
    const errors = await chrome.evaluate('window.renderErrors');
    assert.deepEqual(errors, []);
    const result = {style, fps, frames: ticks.length, buildSeconds: Math.round(buildSeconds), frameSeconds: Math.round(frameSeconds),
      secondsPerFrame: Number(perFrame.toFixed(2)), fullSongMinutes: Number(((buildSeconds + perFrame * FULL_SONG_SECONDS * fps) / 60).toFixed(1)),
      megabytes: Number(((await stat(target)).size / 1048576).toFixed(1)), maxColors: style === 'pixel' ? maxColors : undefined, errors};
    results.push(result);
    console.log(JSON.stringify(result));
  }
} finally {
  await chrome.close();
}
if (styles.length === Object.keys(FILES).length) await writeFile(path.join(outDir, '驗證結果.json'), JSON.stringify(results, null, 2) + '\n');

