// 换景只发生在不透明实物完全遮住画面时；键为进入该镜的衔接。
const OCCLUDERS = {
  P02: P.woodDark, L05: P.paperShade, L06: P.white, L07: P.scarf, L13: P.scarf, L14: P.scarf, I02: P.white,
  L15: P.woodDark, L17: P.woodDark, L18: P.woodDark, L19: P.woodDark, L21: P.woodDark, L31: P.cityNear, L33: P.cityNear,
};
export const WIPE_SECONDS = 0.534;

function clawdA(d, s, table) {
  const a = s.a;
  d.clawd('A', a.x ?? AX + (a.dx ?? 0), a.y ?? AY + (a.dy ?? 0), {facing: a.facing ?? 'right', expression: a.expr ?? 'neutral', action: a.action ?? 'idle', frame: a.frame ?? 0});
  const x = (a.x ?? AX) + (a.dx ?? 0), y = (a.y ?? AY) + (a.dy ?? 0);
  if (a.mouth === 'hum') d.disk('mouthHum', x + 21.5, y + 18.5, 1.2, P.ink);
  if (a.mouth === 'bite') d.rect('mouthBite', x + 20, y + 18.5, 3, 0.9, P.ink);
  if (a.phone) { d.rect('ownPhone', x + 28, y + 11, 4, 8, P.cityNear); d.rect('ownPhoneArm', x + 25, y + 16, 5, 2, P.skin); }
}

function clawdB(d, s) {
  const b = s.b, x = b.x ?? BX, y = b.y ?? BY;
  d.clawd('B', x, y, {facing: b.facing ?? 'left', expression: b.expr ?? 'neutral', action: 'idle', frame: 0});
  if (b.scarf) { d.rect('bScarf', x + 7, y + 14, 16, 3.4, P.scarf); d.poly('bScarfTail', [[x + 19, y + 16], [x + 23, y + 16], [x + 24, y + 24], [x + 20, y + 24]], P.scarf); }
  if (b.tense) d.rect('bTense', x + 9, y + 11, 5, 0.9, P.ink);
}

export function frameAt(t) {
  const index = shotIndexAt(t), shot = SHOTS[index];
  let build = shot, buildT = t, wipe = null;
  const color = OCCLUDERS[shot.id];
  if (color && t - shot.start < WIPE_SECONDS) {
    const w = (t - shot.start) / WIPE_SECONDS;
    wipe = {x: 320 - 700 * w, color};
    if (w < 0.5 && index > 0) { build = SHOTS[index - 1]; buildT = build.end - 1e-4; }
  }
  const d = new Draw();
  const p = span(buildT, build.start, build.end);
  const s = SCRIPT[build.id](p, buildT, {d});
  const ts = tableState(buildT);
  const cam = s.cam ?? [160, 90, 1];

  if (s.set === 'tower') { setTower(d); d.after(); }
  if (s.set === 'phone') setPhone(d, s);
  if (s.set === 'door') {
    setDoor(d, s);
    if (s.suitcaseAt !== undefined) { d.rect('suitcase', s.suitcaseAt, 126, 16, 19, P.metal); d.rect('suitcaseStrap', s.suitcaseAt + 6, 126, 2, 19, P.whiteDark); }
    if (s.a) clawdA(d, s);
    if (s.b) clawdB(d, s);
    if (s.armB) arm(d, 'armB', [224, 134], s.armB);
  }
  if (s.set === 'deck' || s.set === 'home') {
    if (s.set === 'deck') setDeck(d, ts); else setHome(d, {sticker: s.sticker ?? 0});
    if (s.set === 'home' && s.suitcase) { d.rect('homeSuitcase', 78, 165, 18, 30, P.metal); d.rect('homeStrap', 85, 165, 2, 30, P.whiteDark); }
    if (s.a) clawdA(d, s);
    if (s.b) clawdB(d, s);
    const homeTable = s.set === 'home'
      ? {...ts, flip: 0, ticketA: [163, 172], ticketB: [186, 172], used: false, planOpen: 1, envelope: false, penAt: null}
      : ts;
    if (s.planFolded !== undefined) homeTable.planOpen = 1 - s.planFolded;
    table(d, homeTable);
    if (s.dinner) for (const [x, id] of [[175, 'dish1'], [225, 'dish2']]) { d.disk(id, x, 167, 9, P.white); d.disk(`${id}Food`, x, 167, 5, P.warmDark); }
    if (s.key !== undefined) { d.disk('key', s.key, 170, 2.6, P.lamp); d.rect('keyStem', s.key + 2, 169.4, 6, 1.4, P.lamp); }
    if (s.heldScarf && s.armB) d.poly('offeredScarf', [[s.armB[0] - 16, s.armB[1] - 6], [s.armB[0] + 6, s.armB[1] - 6], [s.armB[0] + 4, s.armB[1] + 8], [s.armB[0] - 18, s.armB[1] + 8]], P.scarf);
    if (s.armB) arm(d, 'armB', ARM_B, s.armB);
    if (s.armA) arm(d, 'armA', ARM_A, s.armA);
    if (s.arm) arm(d, 'arm', ARM_A, s.arm);
    if (s.holdScarf) {
      const k = ease(s.holdScarf), hx = mix(270, 134, k), hy = mix(170, 172, k);
      d.poly('heldScarf', [[hx - 10, hy - 7], [hx + 10, hy - 7], [hx + 9, hy + 5], [hx + 5, hy + 19], [hx + 1, hy + 19], [hx, hy + 7], [hx - 3, hy + 19], [hx - 7, hy + 19]], P.scarf);
    }
    if (s.wrist !== undefined) {
      d.line('wristBase', [[128, 176], [152, 182]], P.line, 8);
      d.line('wristFill', [[128, 176], [152, 182]], P.skin, 6);
      d.disk('thumb', 141 + s.wrist * 4, 179, 2.4, P.skinLight);
    }
    if (s.writing && s.arm) d.line('penInHand', [[s.arm[0] - 1, s.arm[1] - 7], [s.arm[0] + 4, s.arm[1] + 1]], P.ink, 1.2);
    if (s.notes !== undefined) d.dots('hummedNotes', [[140, 160 - (s.notes % 2) * 3], [146, 154 - ((s.notes + 1) % 2) * 3]], P.ink, 0.9);
    if (s.tear !== undefined && s.tear > 0 && s.tear < 1) d.disk('tearDrop', mix(130, 180, s.tear), mix(170, 170, s.tear), 1, P.tear);
    if (s.tear >= 1 || (buildT > 185.5 && buildT < 210)) d.disk('tearMark', 184, 170, 1.2, P.tear);
    if (s.sleeve) { const [x, y] = s.sleeve; d.line('sleeve', [[x + 26, y + 60], [x, y]], P.metal, 7); d.rect('tissue', x - 6, y - 5, 8, 7, P.white); }
  }
  return {shot: build.id, cam: {cx: cam[0], cy: cam[1], z: cam[2]}, items: d.items, wipe};
}

