    if (s.heldScarf && s.armB) d.poly('offeredScarf', [[s.armB[0] - 16, s.armB[1] - 6], [s.armB[0] + 6, s.armB[1] - 6], [s.armB[0] + 4, s.armB[1] + 8], [s.armB[0] - 18, s.armB[1] + 8]], P.scarf);
