    if (s.armA) arm(d, 'armA', ARM_A, s.armA);
    if (s.arm) arm(d, 'arm', ARM_A, s.arm);
    if (s.holdScarf) {
      const k = ease(s.holdScarf), hx = mix(270, 134, k), hy = mix(170, 172, k);
      d.poly('heldScarf', [[hx - 10, hy - 7], [hx + 10, hy - 7], [hx + 9, hy + 5], [hx + 5, hy + 19], [hx + 1, hy + 19], [hx, hy + 7], [hx - 3, hy + 19], [hx - 7, hy + 19]], P.scarf);
    }
    if (s.wrist !== undefined) {
      d.line('wristBase', [[128, 176], [152, 182]], P.line, 8);
      d.line('wristFill', [[128, 176], [152, 182]], P.skin, 6);
      d.disk('thumb', 141 + s.wrist * 4, 179, 2.4, P.skinLight);
    }
    if (s.writing && s.arm) d.line('penInHand', [[s.arm[0] - 1, s.arm[1] - 7], [s.arm[0] + 4, s.arm[1] + 1]], P.ink, 1.2);
