import {SHOTS, shotIndexAt} from './shots.js';

export const P = {
  sky0: '#6f8ca6', sky1: '#8aa5b8', sky2: '#a9bdc6', cool: '#b7c6cb',
  cityFar: '#7d96a8', cityMid: '#64808f', cityNear: '#4f6873', lamp: '#f6c35e', lampHi: '#fbe8a8',
  red: '#d85a38', redDark: '#a8432f', white: '#f6efdf', whiteDark: '#d9cfbb',
  floorCool: '#94a9b0', metal: '#7f939c',
  wood: '#b98a5c', woodDark: '#8f6545',
  warm: '#f2dcb0', warmDark: '#e3c08a', floorWarm: '#c99b66',
  paper: '#f5e7c9', paperShade: '#e0cfa8', scarf: '#e5b547', scarfDark: '#c9932f',
  ink: '#352e2a', tear: '#83bdcf', skin: '#da7758', skinLight: '#ed9b75', skinDark: '#b85d47', line: '#713f32',
};

const clamp01 = v => Math.min(1, Math.max(0, v));
const ease = v => { const x = clamp01(v); return x * x * (3 - 2 * x); };
const mix = (a, b, p) => a + (b - a) * ease(p);
const mixArr = (a, b, p) => a.map((v, i) => mix(v, b[i], p));
const span = (t, a, b) => clamp01((t - a) / (b - a));
const rng = seed => { let s = seed >>> 0; return () => { s = (s + 0x6d2b79f5) >>> 0; let x = Math.imul(s ^ (s >>> 15), 1 | s); x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x; return ((x ^ (x >>> 14)) >>> 0) / 4294967296; }; };

class Draw {
  items = [];
  poly(id, pts, color, edge = 'cut') { this.items.push({kind: 'poly', id, pts, color, edge}); }
  rect(id, x, y, w, h, color, edge = 'cut') { this.poly(id, [[x, y], [x + w, y], [x + w, y + h], [x, y + h]], color, edge); }
  disk(id, x, y, r, color, edge = 'cut') { this.poly(id, Array.from({length: 18}, (_, i) => [x + Math.cos(i / 18 * 6.2832) * r, y + Math.sin(i / 18 * 6.2832) * r]), color, edge); }
  line(id, pts, color, width) { this.items.push({kind: 'line', id, pts, color, width}); }
  dots(id, pts, color, size) { this.items.push({kind: 'dots', id, pts, color, size}); }
  text(id, x, y, size, text, color) { this.items.push({kind: 'text', id, x, y, size, text, color}); }
  sky(id, x, y, w, h, stops) { this.items.push({kind: 'sky', id, x, y, w, h, stops}); }
  clawd(id, x, y, opts) { this.items.push({kind: 'clawd', id, x: Math.round(x), y: Math.round(y), ...opts}); }
}

function makeCity(seed, x0, x1, base, [lo, hi], [wLo, wHi], odds) {
  const r = rng(seed), out = [], lamps = [];
  for (let x = x0; x < x1;) {
    const w = Math.round(wLo + r() * (wHi - wLo)), top = Math.round(lo + r() * (hi - lo));
    out.push([x, top, w, base - top]);
    for (let y = top + 3; y < base - 1; y += 4) for (let lx = x + 2; lx < x + w - 1; lx += 3) if (r() < odds) lamps.push([lx, y]);
    x += w;
  }
  return {out, lamps};
}
const CITY = [makeCity(11, 20, 250, 142, [66, 92], [10, 22], 0.06), makeCity(23, 20, 250, 142, [84, 112], [9, 18], 0.14), makeCity(37, 20, 250, 142, [104, 126], [7, 15], 0.28)];
const TOWN = [makeCity(41, -40, 900, 175, [100, 135], [14, 30], 0.08), makeCity(53, -40, 900, 175, [128, 152], [12, 24], 0.2)];

function towerBody(d, cx, base, top, scale, prefix) {
  const half = y => { const k = (base - y) / (base - top); return (k < 0.33 ? 26 - 54 * k : k < 0.68 ? 8.2 - 12 * (k - 0.33) : 4 * (1 - k) + 0.6) * scale; };
  const bands = 7;
  for (let i = 0; i < bands; i++) {
    const a = base - (base - top) * i / bands, b = base - (base - top) * (i + 1) / bands;
    d.poly(`${prefix}band${i}`, [[cx - half(a), a], [cx + half(a), a], [cx + half(b), b], [cx - half(b), b]], i % 2 ? P.white : P.red);
  }
  const deck = base - (base - top) * 0.34, deckHigh = base - (base - top) * 0.68;
  d.rect(`${prefix}deck`, cx - 12 * scale, deck - 3, 24 * scale, 5, P.white);
  d.rect(`${prefix}deck2`, cx - 5 * scale, deckHigh - 2, 10 * scale, 4, P.white);
  d.poly(`${prefix}arch`, [[cx - 12 * scale, base], [cx, base - 22 * scale], [cx + 12 * scale, base]], P.sky2);
}

function setTower(d) {
  d.sky('sky', -60, -40, 1000, 240, [P.sky0, P.sky1, P.sky2, P.cool]);
  for (const [i, c] of [[0, P.cityFar], [1, P.cityMid]]) {
    d.poly(`town${i}`, [[-40, 175], ...TOWN[i].out.flatMap(([x, top, w]) => [[x, top], [x + w, top]]), [900, 175]], c);
    d.dots(`townlamps${i}`, TOWN[i].lamps, i ? P.lamp : P.lampHi, 1);
  }
  towerBody(d, 236, 176, 8, 1.2, 'tower');
  d.rect('street', -60, 172, 1000, 80, P.floorCool, 'torn');
  d.rect('entry', 470, 92, 150, 84, P.white);
  d.rect('entryRoof', 462, 84, 166, 10, P.red);
  d.rect('entryDoor', 505, 120, 44, 56, P.cityNear);
  d.rect('entryPost', 500, 116, 6, 60, P.woodDark);
  d.rect('entryPost2', 548, 116, 6, 60, P.woodDark);
}

function letterFace(d, s) {
  const x = 198, y = 152, w = 36, h = 26;
  const flip = s.flip, mid = Math.abs(flip - 0.5) * 2;
  d.rect('letter', x + w / 2 - w / 2 * mid, y, w * mid, h, P.paper);
  if (mid < 0.5) return;
  if (flip < 0.5) {
    for (let i = 0; i < 4; i++) d.line(`letterline${i}`, [[x + 4, y + 7 + i * 4], [x + 32, y + 7 + i * 4]], P.paperShade, 0.7);
    d.line('melody', [[x + 6, y + 4], [x + 12, y + 2.5], [x + 18, y + 4.5], [x + 26, y + 3]], P.line, 0.7);
    return;
  }
  d.rect('sketchDoor', x + 3, y + 8, 12, 15, P.paperShade);
  d.disk('sketchClock', x + 9, y + 5.5, 2.2, P.white);
  d.text('clockText', x + 3, y + 25, 1.7, '19:00 18:50', P.line);
  d.rect('sketchTokyo', x + 19, y + 8, 14, 15, P.paperShade);
  d.poly('sketchTower', [[x + 25, y + 21], [x + 27, y + 10], [x + 29, y + 21]], P.red);
  d.rect('sketchBee', x + 20.5, y + 17, 3, 4, P.skinDark);
  if (s.drawn1) d.clawd('sketchA1', x + 5.5, y + 13, {facing: 'front', expression: 'neutral', action: 'idle', frame: 0, unit: 0.3});
  if (s.drawn2) d.clawd('sketchA2', x + 25.5, y + 13, {facing: 'back', expression: 'neutral', action: 'idle', frame: 0, unit: 0.3});
  if (s.words) d.text('confession', x + 3, y + 5.2, 4, '其实我很想你'.slice(0, s.words), P.ink);
}

function planFace(d, s) {
  const x = 156, y = 152;
  d.rect('plan', x, y, 36, 26, P.white);
  d.poly('planTower', [[x + 12, y + 16], [x + 15, y + 3], [x + 18, y + 16]], P.red);
  d.rect('planFigA', x + 8, y + 17, 3, 5, P.skinDark);
  d.rect('planFigB', x + 20, y + 17, 3, 5, P.skinDark);
  d.rect('planChair1', x + 27, y + 18, 3, 5, P.woodDark);
  d.rect('planChair2', x + 31, y + 18, 3, 5, P.woodDark);
  d.rect('planLonely', x + 27.4, y + 14.5, 2.2, 3.5, P.skinDark);
  const open = s.planOpen;
  if (open < 1) d.poly('planFold', [[x + 36, y + 26], [x + 36 - 12 * (1 - open) - 1, y + 26], [x + 36, y + 26 - 16 * (1 - open) - 1]], P.whiteDark);
}

function ticket(d, id, [x, y], used) {
  d.rect(id, x - 3.5, y - 2, 7, 4, P.white);
  d.rect(`${id}stub`, x + 1.5, y - 2, 1.6, 4, used ? P.redDark : P.red);
}

function table(d, s) {
  d.rect('tableTop', 150, 148, 100, 38, P.wood);
  d.rect('tableFront', 150, 186, 100, 6, P.woodDark);
  d.rect('tableLegL', 156, 192, 6, 26, P.woodDark);
  d.rect('tableLegR', 238, 192, 6, 26, P.woodDark);
  if (s.envelope !== false) d.rect('envelope', 164, 178.5, 22, 6.5, P.paperShade);
  planFace(d, s);
  letterFace(d, s);
  d.rect('cup', 240, 158, 6, 8, P.cool);
  d.rect('phone', 236, 149, 7, 11, P.cityNear);
  d.rect('phoneGlass', 236.8, 150, 5.4, 9, P.sky2);
  ticket(d, 'ticketA', s.ticketA, s.used);
  ticket(d, 'ticketB', s.ticketB, false);
  if (s.penAt) { const [x, y] = s.penAt; d.line('pen', [[x, y], [x + 5, y + 7]], P.ink, 1.2); }
}

function chairs(d, warm) {
  const c = warm ? P.woodDark : P.metal;
  d.rect('chairABack', 106, 136, 5, 66, c);
  d.rect('chairASeat', 106, 180, 34, 5, warm ? P.wood : P.cityFar);
  d.rect('chairALeg', 108, 185, 4, 33, c);
  d.rect('chairALeg2', 134, 185, 4, 33, c);
  d.rect('chairBBack', 289, 136, 5, 66, c);
  d.rect('chairBSeat', 260, 180, 34, 5, warm ? P.wood : P.cityFar);
  d.rect('chairBLeg', 262, 185, 4, 33, c);
  d.rect('chairBLeg2', 288, 185, 4, 33, c);
}

function scarfOnChair(d, state) {
  if (state === 'draped') {
    d.poly('scarfDraped', [[284, 138], [292, 138], [293, 172], [283, 180], [266, 180], [270, 170], [284, 168]], P.scarf);
    d.line('scarfFold', [[286, 140], [287, 166]], P.scarfDark, 1);
  } else if (state === 'gathered') {
    d.poly('scarfGathered', [[264, 166], [286, 164], [290, 180], [262, 181]], P.scarf);
    d.line('scarfCrease', [[268, 172], [284, 171]], P.scarfDark, 1.2);
  }
}

function setDeck(d, s) {
  d.rect('wall', -40, -30, 420, 205, P.cool, 'torn');
  d.rect('floor', -40, 172, 420, 90, P.floorCool, 'torn');
  d.sky('nightWindow', 24, 16, 226, 128, [P.sky0, P.sky1, P.sky2]);
  CITY.forEach((layer, i) => {
    d.poly(`city${i}`, [[24, 142], ...layer.out.flatMap(([x, top, w]) => [[Math.max(24, x), top], [Math.min(250, x + w), top]]), [250, 142]], [P.cityFar, P.cityMid, P.cityNear][i]);
