function tableState(t) {
  const a0 = [170, 180.5], b0 = [178, 181.5];
  const toA = span(t, 44.2, 47), toB = span(t, 44.2, 46);
  let ticketA = mixArr(a0, [163, 172], toA), ticketB = mixArr(b0, [186, 172], toB);
  const finish = span(t, 251.4, 253.9);
  ticketA = mixArr(ticketA, [168, 175], finish); ticketB = mixArr(ticketB, [176, 175], finish);
  let penAt = [228, 180];
  if ((t > 212.1 && t < 215.1) || (t > 228.5 && t < 236.8)) penAt = null;
  let scarf = 'draped';
  if (t >= 198.6) scarf = 'gathered';
  if (t >= 215.8) scarf = 'held';
  return {
    ticketA, ticketB, used: t > 44.2, penAt, scarf,
    planOpen: span(t, 104.2, 108), flip: span(t, 211.4, 212.3),
    words: Math.floor(7 * span(t, 212.6, 214.9)),
    drawn1: t > 230.6, drawn2: t > 234.9,
    elevator: span(t, 242.5, 246.5), envelope: t > 11,
  };
}

