// 换景只发生在不透明实物完全遮住画面时；键为进入该镜的衔接。
const OCCLUDERS = {
  P02: P.woodDark, L05: P.paperShade, L06: P.white, L07: P.scarf, L13: P.scarf, L14: P.scarf, I02: P.white,
  L15: P.woodDark, L17: P.woodDark, L18: P.woodDark, L19: P.woodDark, L21: P.woodDark, L31: P.cityNear, L33: P.cityNear,
};
export const WIPE_SECONDS = 0.534;

function clawdA(d, s, table) {
  const a = s.a;
  d.clawd('A', a.x ?? AX + (a.dx ?? 0), a.y ?? AY + (a.dy ?? 0), {facing: a.facing ?? 'right', expression: a.expr ?? 'neutral', action: a.action ?? 'idle', frame: a.frame ?? 0});
  const x = (a.x ?? AX) + (a.dx ?? 0), y = (a.y ?? AY) + (a.dy ?? 0);
  if (a.mouth === 'hum') d.disk('mouthHum', x + 21.5, y + 18.5, 1.2, P.ink);
  if (a.mouth === 'bite') d.rect('mouthBite', x + 20, y + 18.5, 3, 0.9, P.ink);
  if (a.phone) { d.rect('ownPhone', x + 28, y + 11, 4, 8, P.cityNear); d.rect('ownPhoneArm', x + 25, y + 16, 5, 2, P.skin); }
}

function clawdB(d, s) {
  const b = s.b, x = b.x ?? BX, y = b.y ?? BY;
  d.clawd('B', x, y, {facing: b.facing ?? 'left', expression: b.expr ?? 'neutral', action: 'idle', frame: 0});
  if (b.scarf) { d.rect('bScarf', x + 7, y + 14, 16, 3.4, P.scarf); d.poly('bScarfTail', [[x + 19, y + 16], [x + 23, y + 16], [x + 24, y + 24], [x + 20, y + 24]], P.scarf); }
  if (b.tense) d.rect('bTense', x + 9, y + 11, 5, 0.9, P.ink);
}

export function frameAt(t) {
  const index = shotIndexAt(t), shot = SHOTS[index];
  let build = shot, buildT = t, wipe = null;
  const color = OCCLUDERS[shot.id];
  if (color && t - shot.start < WIPE_SECONDS) {
    const w = (t - shot.start) / WIPE_SECONDS;
    wipe = {x: 320 - 700 * w, color};
    if (w < 0.5 && index > 0) { build = SHOTS[index - 1]; buildT = build.end - 1e-4; }
  }
  const d = new Draw();
  const p = span(buildT, build.start, build.end);
  const s = SCRIPT[build.id](p, buildT, {d});
  const ts = tableState(buildT);
  const cam = s.cam ?? [160, 90, 1];

  if (s.set === 'tower') { setTower(d); d.after(); }
  if (s.set === 'phone') setPhone(d, s);
  if (s.set === 'door') {
    setDoor(d, s);
    if (s.suitcaseAt !== undefined) { d.rect('suitcase', s.suitcaseAt, 126, 16, 19, P.metal); d.rect('suitcaseStrap', s.suitcaseAt + 6, 126, 2, 19, P.whiteDark); }
    if (s.a) clawdA(d, s);
    if (s.b) clawdB(d, s);
    if (s.armB) arm(d, 'armB', [224, 134], s.armB);
  }
  if (s.set === 'deck' || s.set === 'home') {
    if (s.set === 'deck') setDeck(d, ts); else setHome(d, {sticker: s.sticker ?? 0});
    if (s.set === 'home' && s.suitcase) { d.rect('homeSuitcase', 78, 165, 18, 30, P.metal); d.rect('homeStrap', 85, 165, 2, 30, P.whiteDark); }
    if (s.a) clawdA(d, s);
    if (s.b) clawdB(d, s);
    const homeTable = s.set === 'home'
      ? {...ts, flip: 0, ticketA: [163, 172], ticketB: [186, 172], used: false, planOpen: 1, envelope: false, penAt: null}
      : ts;
    if (s.planFolded !== undefined) homeTable.planOpen = 1 - s.planFolded;
    table(d, homeTable);
    if (s.dinner) for (const [x, id] of [[175, 'dish1'], [225, 'dish2']]) { d.disk(id, x, 167, 9, P.white); d.disk(`${id}Food`, x, 167, 5, P.warmDark); }
    if (s.key !== undefined) { d.disk('key', s.key, 170, 2.6, P.lamp); d.rect('keyStem', s.key + 2, 169.4, 6, 1.4, P.lamp); }
    if (s.heldScarf && s.armB) d.poly('offeredScarf', [[s.armB[0] - 16, s.armB[1] - 6], [s.armB[0] + 6, s.armB[1] - 6], [s.armB[0] + 4, s.armB[1] + 8], [s.armB[0] - 18, s.armB[1] + 8]], P.scarf);
    if (s.armB) arm(d, 'armB', ARM_B, s.armB);
    if (s.armA) arm(d, 'armA', ARM_A, s.armA);
    if (s.arm) arm(d, 'arm', ARM_A, s.arm);
    if (s.holdScarf) {
      const k = ease(s.holdScarf), hx = mix(270, 134, k), hy = mix(170, 172, k);
      d.poly('heldScarf', [[hx - 10, hy - 7], [hx + 10, hy - 7], [hx + 9, hy + 5], [hx + 5, hy + 19], [hx + 1, hy + 19], [hx, hy + 7], [hx - 3, hy + 19], [hx - 7, hy + 19]], P.scarf);
    }
    if (s.wrist !== undefined) {
      d.line('wristBase', [[128, 176], [152, 182]], P.line, 8);
      d.line('wristFill', [[128, 176], [152, 182]], P.skin, 6);
      d.disk('thumb', 141 + s.wrist * 4, 179, 2.4, P.skinLight);
    }
    if (s.writing && s.arm) d.line('penInHand', [[s.arm[0] - 1, s.arm[1] - 7], [s.arm[0] + 4, s.arm[1] + 1]], P.ink, 1.2);
    if (s.notes !== undefined) d.dots('hummedNotes', [[140, 160 - (s.notes % 2) * 3], [146, 154 - ((s.notes + 1) % 2) * 3]], P.ink, 0.9);
    if (s.tear !== undefined && s.tear > 0 && s.tear < 1) d.disk('tearDrop', mix(130, 180, s.tear), mix(170, 170, s.tear), 1, P.tear);
    if (s.tear >= 1 || (buildT > 185.5 && buildT < 210)) d.disk('tearMark', 184, 170, 1.2, P.tear);
    if (s.sleeve) { const [x, y] = s.sleeve; d.line('sleeve', [[x + 26, y + 60], [x, y]], P.metal, 7); d.rect('tissue', x - 6, y - 5, 8, 7, P.white); }
  }
  return {shot: build.id, cam: {cx: cam[0], cy: cam[1], z: cam[2]}, items: d.items, wipe};
}

import {drawCharacter, CHARACTER_COLORS} from '../../assets/clawd/character.js';

// 借 character.js 取得角色几何：录下它的每个色块，三种画风都用同一份数据。
const cache = new Map();
export function clawdRects({facing, expression, action, frame}) {
  const key = `${facing}|${expression}|${action}|${frame}`;
  if (cache.has(key)) return cache.get(key);
  const rects = [];
  let sx = 1, ox = 0, stack = [], fill = null;
  const recorder = {
    canvas: {},
    save() { stack.push([sx, ox]); }, restore() { [sx, ox] = stack.pop(); },
    translate(x) { ox += x * sx; }, scale(x) { sx *= x; },
    set fillStyle(v) { fill = v; }, get fillStyle() { return fill; },
    imageSmoothingEnabled: false,
    fillRect(x, y, w, h) { rects.push({x: sx > 0 ? ox + x : ox - x - w, y, w, h, color: fill}); },
  };
  drawCharacter(recorder, {x: 0, y: 0, scale: 1, facing, expression, action, frame});
  cache.set(key, rects);
  return rects;
}
export {CHARACTER_COLORS};

export const toScreen = (cam, x, y) => [(x - cam.cx) * cam.z + 160, (y - cam.cy) * cam.z + 90];

import {clawdRects, toScreen} from './geometry.js';

const W = 320, H = 180, U = 6;
const BAYER = [[0, 32, 8, 40, 2, 34, 10, 42], [48, 16, 56, 24, 50, 18, 58, 26], [12, 44, 4, 36, 14, 46, 6, 38],
  [60, 28, 52, 20, 62, 30, 54, 22], [3, 35, 11, 43, 1, 33, 9, 41], [51, 19, 59, 27, 49, 17, 57, 25],
  [15, 47, 7, 39, 13, 45, 5, 37], [63, 31, 55, 23, 61, 29, 53, 21]];
const rgba = hex => { const n = parseInt(hex.slice(1), 16); return (255 << 24 | (n & 255) << 16 | (n >> 8 & 255) << 8 | n >> 16) >>> 0; };
const known = new Map();
const c32 = hex => { if (!known.has(hex)) known.set(hex, rgba(hex)); return known.get(hex); };

export function createPixel() {
  const native = document.createElement('canvas');
  native.width = W; native.height = H;
  const ctx = native.getContext('2d');
  const image = ctx.createImageData(W, H);
  const buf = new Uint32Array(image.data.buffer);
  const glyph = document.createElement('canvas');
  glyph.width = W; glyph.height = 40;
  const glyphCtx = glyph.getContext('2d', {willReadFrequently: true});

  const fillPoly = (pts, value) => {
    const ys = pts.map(p => p[1]);
    for (let y = Math.max(0, Math.floor(Math.min(...ys))); y <= Math.min(H - 1, Math.ceil(Math.max(...ys))); y++) {
      const xs = [];
      pts.forEach(([ax, ay], i) => {
        const [bx, by] = pts[(i + 1) % pts.length];
        if ((ay <= y + 0.5) !== (by <= y + 0.5)) xs.push(ax + (y + 0.5 - ay) * (bx - ax) / (by - ay));
      });
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        for (let x = Math.max(0, Math.round(xs[k])); x < Math.min(W, Math.round(xs[k + 1])); x++) buf[y * W + x] = value;
      }
    }
  };
  const fillRect = (x, y, w, h, value) => {
    const x0 = Math.max(0, Math.round(x)), x1 = Math.min(W, Math.round(x + w)), y0 = Math.max(0, Math.round(y)), y1 = Math.min(H, Math.round(y + h));
    for (let j = y0; j < y1; j++) for (let i = x0; i < x1; i++) buf[j * W + i] = value;
  };

  function drawItem(item, cam) {
    if (item.kind === 'poly') return fillPoly(item.pts.map(([x, y]) => toScreen(cam, x, y)), c32(item.color));
    if (item.kind === 'line') {
      const r = Math.max(0.5, item.width * cam.z / 2);
      for (let i = 1; i < item.pts.length; i++) {
        const [ax, ay] = toScreen(cam, ...item.pts[i - 1]), [bx, by] = toScreen(cam, ...item.pts[i]);
        const len = Math.hypot(bx - ax, by - ay) || 1, nx = -(by - ay) / len * r, ny = (bx - ax) / len * r;
        fillPoly([[ax + nx, ay + ny], [bx + nx, by + ny], [bx - nx, by - ny], [ax - nx, ay - ny]], c32(item.color));
      }
      return;
    }
    if (item.kind === 'dots') {
      const size = Math.max(1, Math.round(item.size * cam.z));
      for (const [x, y] of item.pts) { const [sx, sy] = toScreen(cam, x, y); fillRect(sx, sy, size, size, c32(item.color)); }
      return;
    }
    if (item.kind === 'sky') {
      const [sx, sy] = toScreen(cam, item.x, item.y), [ex, ey] = toScreen(cam, item.x + item.w, item.y + item.h);
      const stops = item.stops.map(c32);
      for (let y = Math.max(0, Math.round(sy)); y < Math.min(H, Math.round(ey)); y++) for (let x = Math.max(0, Math.round(sx)); x < Math.min(W, Math.round(ex)); x++) {
        const t = ((y - sy) / (ey - sy)) * (stops.length - 1), base = Math.min(stops.length - 1, Math.floor(t));
        const pick = t - base > (BAYER[y & 7][x & 7] + 0.5) / 64 ? Math.min(stops.length - 1, base + 1) : base;
        buf[y * W + x] = stops[pick];
      }
      return;
    }
    if (item.kind === 'clawd') {
      const unit = (item.unit ?? 1) * cam.z, [ox, oy] = toScreen(cam, item.x, item.y);
      for (const rect of clawdRects(item)) fillRect(ox + rect.x * unit, oy + rect.y * unit, rect.w * unit, rect.h * unit, c32(rect.color));
      return;
    }
    if (item.kind === 'text') {
      const px = Math.max(5, Math.round(item.size * cam.z)), [sx, sy] = toScreen(cam, item.x, item.y);
      glyphCtx.clearRect(0, 0, W, 40);
      glyphCtx.fillStyle = '#000'; glyphCtx.font = `${px}px "PingFang SC","Heiti SC",sans-serif`; glyphCtx.textBaseline = 'alphabetic';
      glyphCtx.fillText(item.text, 2, 30);
      const data = glyphCtx.getImageData(0, 0, W, 40).data, value = c32(item.color);
      for (let y = 0; y < 40; y++) for (let x = 0; x < W; x++) {
        if (data[(y * W + x) * 4 + 3] < 110) continue;
        const dx = Math.round(sx) + x - 2, dy = Math.round(sy) + y - 30;
        if (dx >= 0 && dy >= 0 && dx < W && dy < H) buf[dy * W + dx] = value;
      }
    }
  }

  const canvas = document.createElement('canvas');
  canvas.width = W * U; canvas.height = H * U; document.body.append(canvas);
  const out = canvas.getContext('2d');
  out.imageSmoothingEnabled = false;

  function render(frame) {
    buf.fill(c32('#b7c6cb'));
    for (const item of frame.items) drawItem(item, frame.cam);
    if (frame.wipe) {
      fillRect(frame.wipe.x, 0, 380, H, c32(frame.wipe.color));
      fillRect(frame.wipe.x, 0, 4, H, c32('#713f32'));
    }
    ctx.putImageData(image, 0, 0);
    out.drawImage(native, 0, 0, canvas.width, canvas.height);
  }
  return {canvas, native, render, mime: 'image/png'};
}

// node render.mjs film [pixel paper crayon]：输出全片到 輸出/（不进入 Git）
// node render.mjs sheet <style> [秒…]：把指定时刻的画面拼成检查图，存到 .agent/work/mv-check/
import {spawn} from 'node:child_process';
import {mkdir, stat, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
import {openChrome, root} from '../開場樣圖/v2/chrome.mjs';
import {FPS, SHOTS, SONG_SECONDS, frameTimes} from './shots.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const FILES = {pixel: '01-像素遊戲', paper: '02-紙藝拼貼', crayon: '03-蠟筆手繪'};
const AUDIO = path.join(root, '會呼吸的痛/會呼吸的痛.m4a');
const [mode, ...args] = process.argv.slice(2);
const chrome = await openChrome();

const png = async () => Buffer.from(await chrome.evaluate(`window.art.canvas.toDataURL('image/png').split(',')[1]`), 'base64');

const CHECK_PIXEL = `(() => {
  const c = window.art.canvas, d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data, colors = new Set();
  let blocks = true;
  for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) {
    const i = (y * c.width + x) * 4, j = ((y - y % 6) * c.width + (x - x % 6)) * 4;
    colors.add(d[i] * 65536 + d[i + 1] * 256 + d[i + 2]);
    if (d[i] !== d[j] || d[i + 1] !== d[j + 1] || d[i + 2] !== d[j + 2]) blocks = false;
  }
  return {colors: colors.size, blocks};
})()`;

async function sheet(style, times) {
  const dir = path.join(root, '.agent/work/mv-check');
  await mkdir(dir, {recursive: true});
  await chrome.openStyle(style, here);
  const name = `${style}-${times[0].toFixed(1)}`;
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-i', '-', '-vf', 'scale=640:-1,tile=3x3', '-frames:v', '1', path.join(dir, `${name}.png`)], {stdio: ['pipe', 'inherit', 'inherit']});
  const done = new Promise((ok, fail) => ffmpeg.once('exit', c => (c === 0 ? ok() : fail(new Error(`ffmpeg ${c}`)))));
  for (let i = 0; i < 9; i++) {
    if (i < times.length) await chrome.evaluate(`window.renderAt(${times[i]}, ${i})`);
    ffmpeg.stdin.write(await png());
  }
  ffmpeg.stdin.end();
  await done;
  assert.deepEqual(await chrome.evaluate('window.renderErrors'), []);
  console.log(path.join(dir, `${name}.png`));
}

async function film(style) {
  const fps = FPS[style], times = frameTimes(fps), outDir = path.join(here, '輸出');
  await mkdir(outDir, {recursive: true});
  const target = path.join(outDir, `${FILES[style]}.mp4`), started = Date.now();
  await chrome.openStyle(style, here);
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(fps), '-i', '-', '-i', AUDIO,
    '-map', '0:v', '-map', '1:a', '-r', '24', '-c:v', 'libx264', '-crf', '18', '-preset', 'medium', '-pix_fmt', 'yuv420p',
    '-c:a', 'aac', '-b:a', '192k', '-t', String(SONG_SECONDS), '-movflags', '+faststart', target], {stdio: ['pipe', 'inherit', 'inherit']});
  const done = new Promise((ok, fail) => ffmpeg.once('exit', c => (c === 0 ? ok() : fail(new Error(`ffmpeg ${c}`)))));
  let maxColors = 0;
  for (let i = 0; i < times.length; i++) {
    await chrome.evaluate(`window.renderAt(${times[i]}, ${i})`);
    if (style === 'pixel' && i % 24 === 0) {
      const check = await chrome.evaluate(CHECK_PIXEL);
      assert.ok(check.colors <= 32, `${times[i]} 秒 ${check.colors} 色`);
      assert.equal(check.blocks, true, `${times[i]} 秒色块不完整`);
      maxColors = Math.max(maxColors, check.colors);
    }
    if (!ffmpeg.stdin.write(await png())) await new Promise(ok => ffmpeg.stdin.once('drain', ok));
    if (i % 200 === 0) console.log(`${style} ${i}/${times.length} ${Math.round((Date.now() - started) / 1000)}s`);
  }
  ffmpeg.stdin.end();
  await done;
  assert.deepEqual(await chrome.evaluate('window.renderErrors'), []);
  return {style, fps, frames: times.length, minutes: Number(((Date.now() - started) / 60000).toFixed(1)),
    megabytes: Number(((await stat(target)).size / 1048576).toFixed(1)), maxColors: style === 'pixel' ? maxColors : undefined};
}

try {
  if (mode === 'sheet') {
    const [style, ...rest] = args;
    await sheet(style, rest.map(Number));
  } else if (mode === 'shots') {
    const [style, from, to] = args;
    const picks = SHOTS.slice(Number(from), Number(to)).map(s => s.start + (s.end - s.start) * 0.72);
    await sheet(style, picks);
  } else if (mode === 'film') {
    const results = [];
    for (const style of args.length ? args : Object.keys(FILES)) {
      results.push(await film(style));
      console.log(JSON.stringify(results.at(-1)));
    }
    await writeFile(path.join(here, '驗證結果.json'), JSON.stringify(results, null, 2) + '\n');
  } else throw new Error('用法：render.mjs film|sheet|shots');
} finally {
  await chrome.close();
}

