// 输出分镜：每镜一张 1920×1080 关键画面，以及带镜号与时间的总览图。
import {spawn} from 'node:child_process';
import {mkdir, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
import {openChrome} from '../開場樣圖/v2/chrome.mjs';
import {SHOTS} from './shots.js';
import {KEY_TIMES} from './film.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const outDir = path.join(here, '分鏡');
await mkdir(outDir, {recursive: true});
const chrome = await openChrome();

const clock = s => `${String(Math.floor(s / 60)).padStart(2, '0')}:${(s % 60).toFixed(3).padStart(6, '0')}`;
const keyTime = shot => KEY_TIMES[shot.id] ?? shot.start + (shot.end - shot.start) * 0.72;

try {
  await chrome.openStyle('storyboard', here);
  const frames = [];
  for (const shot of SHOTS) {
    const t = keyTime(shot);
    await chrome.evaluate(`window.renderAt(${t})`);
    const check = await chrome.evaluate(`(() => {
      const c = window.art.native, d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data, colors = new Set();
      for (let i = 0; i < d.length; i += 4) colors.add(d[i] * 65536 + d[i + 1] * 256 + d[i + 2]);
      return colors.size;
    })()`);
    assert.ok(check <= 32, `${shot.id} 用了 ${check} 色`);
    const file = path.join(outDir, `${shot.id}.png`);
    await writeFile(file, Buffer.from(await chrome.evaluate(`window.art.canvas.toDataURL('image/png').split(',')[1]`), 'base64'));
    frames.push({id: shot.id, start: clock(shot.start), end: clock(shot.end), keyTime: Number(t.toFixed(3)), colors: check});
  }
  assert.deepEqual(await chrome.evaluate('window.renderErrors'), []);
  await writeFile(path.join(outDir, '驗證結果.json'), JSON.stringify(frames, null, 2) + '\n');

  const COLS = 6, ROWS = Math.ceil(SHOTS.length / COLS), TW = 480, TH = 270;
  const labels = frames.map((f, i) => {
    const x = (i % COLS) * TW + 6, y = Math.floor(i / COLS) * TH + 22;
    return `drawtext=fontfile=/System/Library/Fonts/Menlo.ttc:text='${f.id}  ${f.start.replace(/:/g, '\\:')}':x=${x}:y=${y}:fontsize=18:fontcolor=white:box=1:boxcolor=0x352e2acc:boxborderw=4`;
  }).join(',');
  const inputs = frames.flatMap(f => ['-i', path.join(outDir, `${f.id}.png`)]);
  const grid = frames.map((_, i) => `[${i}:v]scale=${TW}:${TH}:flags=neighbor[t${i}]`).join(';');
  const layout = frames.map((_, i) => `${(i % COLS) * TW}_${Math.floor(i / COLS) * TH}`).join('|');
  const stack = `${frames.map((_, i) => `[t${i}]`).join('')}xstack=inputs=${frames.length}:layout=${layout}:fill=0xeee8d9,pad=${COLS * TW}:${ROWS * TH}:0:0:0xeee8d9,${labels}`;
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', ...inputs, '-filter_complex', `${grid};${stack}`, '-frames:v', '1', path.join(outDir, '分鏡總覽.png')], {stdio: 'inherit'});
  await new Promise((ok, fail) => ffmpeg.once('exit', c => (c === 0 ? ok() : fail(new Error(`ffmpeg ${c}`)))));
  console.log(`status=ok shots=${frames.length} maxColors=${Math.max(...frames.map(f => f.colors))}`);
} finally {
  await chrome.close();
}

