// node render.mjs film [pixel paper crayon]：输出全片到 輸出/（不进入 Git）
// node render.mjs sheet <style> [秒…]：把指定时刻的画面拼成检查图，存到 .agent/work/mv-check/
import {spawn} from 'node:child_process';
import {mkdir, stat, writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import assert from 'node:assert/strict';
import {openChrome, root} from '../開場樣圖/v2/chrome.mjs';
import {FPS, SHOTS, SONG_SECONDS, frameTimes} from './shots.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const FILES = {pixel: '01-像素遊戲', paper: '02-紙藝拼貼', crayon: '03-蠟筆手繪'};
const AUDIO = path.join(root, '會呼吸的痛/會呼吸的痛.m4a');
const [mode, ...args] = process.argv.slice(2);
const chrome = await openChrome();

const png = async () => Buffer.from(await chrome.evaluate(`window.art.canvas.toDataURL('image/png').split(',')[1]`), 'base64');

const CHECK_PIXEL = `(() => {
  const c = window.art.canvas, d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data, colors = new Set();
  let blocks = true;
  for (let y = 0; y < c.height; y++) for (let x = 0; x < c.width; x++) {
    const i = (y * c.width + x) * 4, j = ((y - y % 6) * c.width + (x - x % 6)) * 4;
    colors.add(d[i] * 65536 + d[i + 1] * 256 + d[i + 2]);
    if (d[i] !== d[j] || d[i + 1] !== d[j + 1] || d[i + 2] !== d[j + 2]) blocks = false;
  }
  return {colors: colors.size, blocks};
})()`;

async function sheet(style, times) {
  const dir = path.join(root, '.agent/work/mv-check');
  await mkdir(dir, {recursive: true});
  await chrome.openStyle(style, here);
  const name = `${style}-${times[0].toFixed(1)}`;
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-i', '-', '-vf', 'scale=640:-1,tile=3x3', '-frames:v', '1', path.join(dir, `${name}.png`)], {stdio: ['pipe', 'inherit', 'inherit']});
  const done = new Promise((ok, fail) => ffmpeg.once('exit', c => (c === 0 ? ok() : fail(new Error(`ffmpeg ${c}`)))));
  for (let i = 0; i < 9; i++) {
    if (i < times.length) await chrome.evaluate(`window.renderAt(${times[i]}, ${i})`);
    ffmpeg.stdin.write(await png());
  }
  ffmpeg.stdin.end();
  await done;
  assert.deepEqual(await chrome.evaluate('window.renderErrors'), []);
  console.log(path.join(dir, `${name}.png`));
}

async function film(style) {
  const fps = FPS[style], times = frameTimes(fps), outDir = path.join(here, '輸出');
  await mkdir(outDir, {recursive: true});
  const target = path.join(outDir, `${FILES[style]}.mp4`), started = Date.now();
  await chrome.openStyle(style, here);
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(fps), '-i', '-', '-i', AUDIO,
    '-map', '0:v', '-map', '1:a', '-r', '24', '-c:v', 'libx264', '-crf', '18', '-preset', 'medium', '-pix_fmt', 'yuv420p',
    '-c:a', 'aac', '-b:a', '192k', '-t', String(SONG_SECONDS), '-movflags', '+faststart', target], {stdio: ['pipe', 'inherit', 'inherit']});
  const done = new Promise((ok, fail) => ffmpeg.once('exit', c => (c === 0 ? ok() : fail(new Error(`ffmpeg ${c}`)))));
  let maxColors = 0;
  for (let i = 0; i < times.length; i++) {
    await chrome.evaluate(`window.renderAt(${times[i]}, ${i})`);
    if (style === 'pixel' && i % 24 === 0) {
      const check = await chrome.evaluate(CHECK_PIXEL);
      assert.ok(check.colors <= 32, `${times[i]} 秒 ${check.colors} 色`);
      assert.equal(check.blocks, true, `${times[i]} 秒色块不完整`);
      maxColors = Math.max(maxColors, check.colors);
    }
    if (!ffmpeg.stdin.write(await png())) await new Promise(ok => ffmpeg.stdin.once('drain', ok));
    if (i % 200 === 0) console.log(`${style} ${i}/${times.length} ${Math.round((Date.now() - started) / 1000)}s`);
  }
  ffmpeg.stdin.end();
  await done;
  assert.deepEqual(await chrome.evaluate('window.renderErrors'), []);
  return {style, fps, frames: times.length, minutes: Number(((Date.now() - started) / 60000).toFixed(1)),
    megabytes: Number(((await stat(target)).size / 1048576).toFixed(1)), maxColors: style === 'pixel' ? maxColors : undefined};
}

try {
  if (mode === 'sheet') {
    const [style, ...rest] = args;
    await sheet(style, rest.map(Number));
  } else if (mode === 'shots') {
    const [style, from, to] = args;
    const picks = SHOTS.slice(Number(from), Number(to)).map(s => s.start + (s.end - s.start) * 0.72);
    await sheet(style, picks);
  } else if (mode === 'film') {
    const results = [];
    for (const style of args.length ? args : Object.keys(FILES)) {
      results.push(await film(style));
      console.log(JSON.stringify(results.at(-1)));
    }
    await writeFile(path.join(here, '驗證結果.json'), JSON.stringify(results, null, 2) + '\n');
  } else throw new Error('用法：render.mjs film|sheet|shots');
} finally {
  await chrome.close();
}

