  let scarf = 'draped';
  if (t >= 198.6) scarf = 'gathered';
  if (t >= 215.8) scarf = 'held';
  return {
    ticketA, ticketB, used: t > 44.2, penAt: writing ? null : PEN_REST, scarf,
