const CITY = [makeCity(11, 20, 210, 142, [66, 92], [10, 22], 0.06), makeCity(23, 20, 210, 142, [84, 112], [9, 18], 0.14), makeCity(37, 20, 210, 142, [104, 126], [7, 15], 0.28)];
