  P02: (p, t) => ({set: 'deck', cam: mixArr([110, 140, 1.5], CAM.wide, span(t, 9.2, 14.21)), a: {expr: 'neutral', facing: 'right'}}),
  L01: (p) => ({set: 'deck', cam: mixArr(CAM.wide, [130, 128, 1.6], p), a: {expr: 'neutral', facing: 'back'}}),
