  L13: (p, t) => ({set: 'home', cam: mixArr([190, 165, 2.2], [180, 152, 1.5], span(t, 93.3, 95.3)), a: {expr: 'neutral', facing: 'right', phone: true}, b: {expr: 'shy', dx: -14}, heldScarf: true}),
  L14: (p, t) => ({set: 'deck', cam: [180, 152, 1.5], a: {...SAD, action: t > 98.9 ? 'hug' : 'idle'}}),
  I01: (p, t) => ({set: 'deck', cam: mixArr([180, 152, 1.5], CAM.plan, span(t, 102.7, 104.5)), a: {...SAD, dx: Math.round(mix(mix(0, 6, span(t, 102.7, 104)), 0, span(t, 108, 109)))}}),
  I02: (p, t) => ({set: 'home', cam: mixArr(CAM.plan, [200, 160, 2.4], span(t, 112.7, 121)), b: {expr: 'sad', scarf: true, dx: Math.round(-8 * span(t, 112.7, 114))}, emptyA: true, planFolded: span(t, 114, 119)}),
  L15: (p) => ({set: 'home', cam: mixArr([200, 160, 2.4], [185, 158, 1.7], p), a: {expr: 'neutral', facing: 'right', phone: true}, b: {expr: 'happy', scarf: true, tense: true}, planFolded: 1}),
  L16: (p, t) => ({set: 'home', cam: mixArr([185, 158, 1.7], [222, 182, 4], span(t, 131.7, 134)), b: {expr: 'sad', scarf: true}, a: {expr: 'neutral', facing: 'right', phone: true}, planFolded: 1,
